    "SchedulesCancelled",
  ],
  worker: ["WorkerAttemptStarted", "WorkerLeaseExpired"],
  verification: [
    "VerificationOpened",
    "VerificationDispatchRequested",
    "CommandPersisted",
    "WorkerAttemptStarted",
    "WorkerHeartbeat",
    "WorkerLeaseExpired",
    "CommandResult",
    "VerificationContinuation",
    "VerificationSubjectSubmitted",
  ],
  feedback: [
    "FeedbackAuditOpened",
    "FeedbackAuditRequested",
    "FeedbackAuditExecutionRequested",
    "CommandPersisted",
    "CommandResult",
    ...SEMANTIC_CORRECTIONS,
  ],
  repair: repairEventTypes,
  sourceChange: sourceChangeEventTypes,
  resident: residentEventTypes,
} as const;
export type FoldedSlice = keyof typeof sliceEventTypes;
export function selectEventSlice(
  state: SkeletonState,
  event: Event,
): FoldedSlice {
  if (
    event.type === "RepairOpened" ||
    (state.repair && state.repair.workstreamId === event.workstreamId)
  )
    return "repair";
  if (
    sourceChangeEventTypes.some((type) => type === event.type) ||
    (selectSourceChangeSlice(state).workstreamId !== undefined &&
      selectSourceChangeSlice(state).workstreamId === event.workstreamId)
  )
    return "sourceChange";
  if (
    selectResidentSlice(state) !== undefined ||
    residentEventTypes.some((type) => type === event.type)
  )
    return "resident";
  if (
    event.type === "FeedbackAuditOpened" ||
    selectFeedbackSlice(state) !== undefined
  )
    return "feedback";
  if (selectVerificationSlice(state) !== undefined) return "verification";
  if (sliceEventTypes.worker.some((type) => type === event.type))
    return "worker";
  return "walking";
}

