/** The skeleton owns the layout of its replayable environment state; replay and
 * the live folds read the same kernel-facing slice, so they cannot drift. */
export function projectRuntimeEnvironment(
  state: RuntimeState,
): Omit<KernelEnv, "now" | "predicates"> {
  return kernelStateFromRuntime(state);
}

const statePresence = (state: JsonValue): JsonValue | undefined =>
  state !== null && !Array.isArray(state) && typeof state === "object"
    ? (state as Readonly<Record<string, JsonValue>>)["presence"]
    : undefined;

export const seiriPredicates: PredicateRegistry = {
  "operator.away": { 1: ({ state }) => statePresence(state) === "away" },
  "operator.returned": {
    1: ({ state }) => statePresence(state) === "returned",
  },
  "operator.return-event": {
    1: ({ state, event }) =>
      statePresence(state) === "returned" &&
      event?.type === "OperatorPresenceChanged" &&
      event.payload !== null &&
      !Array.isArray(event.payload) &&
      typeof event.payload === "object" &&
      (event.payload as Readonly<Record<string, JsonValue>>)["presence"] ===
        "returned",
  },
};

export function compileLoadoutProgram(
  equipped: Loadout,
  baseCommit = "fixture-base",
): CompiledProgram {
  const result = compileLoadout(equipped, seiriEnvironment(baseCommit));
  if (!result.ok)
    throw new Error(
      result.diagnostics.map((entry) => entry.message).join("\n"),
    );
  return result.program;
}

export function compileWorkOrder(
  equipped: Loadout,
  baseCommit = "fixture-base",
): WorkOrder {
  return compileLoadoutProgram(equipped, baseCommit).workOrder;
}

export const initialState = (): RuntimeState => ({
  presence: "returned",
  rngState: 17,
  policy: { maintenance: "absent-only" },
  loadout: null,
  artifactIdentity: null,
  compilationEnvironment: null,
  equippedEventId: null,
  identityEnforcementEventId: null,
  artifactIdentityBlocked: false,
  workOrder: null,
  candidates: [],
  verified: false,
  verificationCompleted: false,
  pulseSeen: false,
  inspectionCompleted: false,
  deletionRefused: false,
  queuedPulseNoOp: false,
  authority: null,
  revocationEvents: [],
  program: null,
  commandResult: null,
  pendingCommand: null,
  authorizationEvidence: [],
  deletionPaths: [],
  refusalReason: null,
  persistedEffect: null,
  noOpEvidence: [],
  cancelledScheduleIds: [],
  activeScheduleIds: [],
  redispatchedCommandIds: [],
  beaconObservations: [],
  beaconSweep: null,
  workerEpisodeId: null,
  workerLeaseExpired: false,
});

const asObject = (
  value: JsonValue,
): Readonly<Record<string, JsonValue>> | undefined =>
  value !== null && !Array.isArray(value) && typeof value === "object"
    ? (value as Readonly<Record<string, JsonValue>>)
    : undefined;

const stringField = (value: JsonValue, key: string): string | undefined => {
  const candidate = asObject(value)?.[key];
  return typeof candidate === "string" ? candidate : undefined;
};

const stringArrayField = (value: JsonValue, key: string): readonly string[] => {
  const candidate = asObject(value)?.[key];
  return Array.isArray(candidate) &&
    candidate.every((item) => typeof item === "string")
    ? candidate
    : [];
};

const candidatesField = (value: JsonValue): readonly Candidate[] => {
  const candidates = asObject(value)?.["candidates"];
  return Array.isArray(candidates)
    ? (candidates as unknown as readonly Candidate[])
    : [];
};

const eventFromState = (value: JsonValue, name: string): Event => {
  if (value === null) throw new Error(`runtime state lacks ${name}`);
  return value as unknown as Event;
};

const workOrderFromValue = (value: JsonValue): WorkOrder => {
  if (value === null) throw new Error("runtime state lacks WorkOrder");
  return value as unknown as WorkOrder;
};

const cadenceFromCompiled = (compiled: CompiledProgram) => {
  const value = compiled.cadences[0];
  if (value === undefined) throw new Error("compiled loadout lacks cadence");
  return value;
};

const authorityFromState = (state: WalkingSkeletonSlice): AuthorityEnvelope =>
  state.authority as unknown as AuthorityEnvelope;

const revocationsFromState = (state: WalkingSkeletonSlice): readonly Event[] =>
  state.revocationEvents as unknown as readonly Event[];

const persistedContinuation = (
  value: unknown,
  location: string,
): ExecutableProgramV1 => {
  const decoded = decodeContinuation(value);
  if (!decoded.ok) throw new Error(`${location}: ${decoded.message}`);
  return decoded.value;
};
const programFromState = (state: WalkingSkeletonSlice): ExecutableProgramV1 =>
  persistedContinuation(state.program, "runtime program");

const requiredContinuation = (
  decision: ProgramDecision<WalkingSkeletonSlice>,
): ExecutableProgramV1 => {
  if (decision.continuation === undefined)
    throw new Error("kernel program decision lacks a continuation");
  return decision.continuation;
};

export const workOrderFromState = (state: WalkingSkeletonSlice): WorkOrder =>
  workOrderFromValue(state.workOrder);

export const commandFromState = (state: WalkingSkeletonSlice): Command => {
  if (state.pendingCommand === null)
    throw new Error("runtime state lacks pending command");
  return state.pendingCommand as unknown as Command;
};

const inspectIntent = (workOrder: WorkOrder): ActIntent => ({
  kind: "Act",
  effect: "repo.inspect",
  resource: "inspections",
  payload: { workOrder: workOrder as unknown as JsonValue },
});

const verificationProgram = (
  workOrder: WorkOrder,
  at: number,
  verificationSubject: string,
): ExecutableProgramV1 => {
  const inspect = inspectIntent(workOrder);
  const id = commandId(WORKSTREAM, EPISODE, 1, 0);
  return Program.Invoke(id, inspect, {
    [verificationSubject]: Program.Emit(
      draft("VerificationRequested", at + 2, { commandId: id }),
      Program.Done(),
    ),
  });
};

const draft = (
  type: string,
  occurredAt: number,
  payload: JsonValue,
  correlationId?: string,
  causationId?: string,
): EventDraft => ({
  schemaVersion: 1,
  type,
  occurredAt,
  actorId: ACTOR,
  workstreamId: WORKSTREAM,
  episodeId: EPISODE,
  ...(correlationId === undefined ? {} : { correlationId }),
  ...(causationId === undefined ? {} : { causationId }),
  payload,
});

const linkedDraft = (
  event: EventDraft,
  correlationId: string | undefined,
  causationId: string,
): EventDraft => ({
  schemaVersion: event.schemaVersion,
  type: event.type,
  occurredAt: event.occurredAt,
  actorId: event.actorId,
  workstreamId: event.workstreamId,
  ...(event.episodeId === undefined ? {} : { episodeId: event.episodeId }),
  ...(correlationId === undefined ? {} : { correlationId }),
  causationId,
  payload: event.payload,
});

const observed = <S>(
  state: S,
  event: Event,
  branch = "observed",
): SliceDecision<S> => ({
  state,
  intents: [],
  schedules: [],
  trace: {
    reactorId: "seiri-reactor",
    reactorVersion: "1",
    branchPath: [event.type, branch],
    envInputs: ["event"],
    cadenceEvaluations: [],
  },
});

const workerNoOp = (
  state: WalkingSkeletonSlice,
  event: Event,
  reason: string,
): Decision<WalkingSkeletonSlice> => ({
  ...observed(state, event, reason),
  intents: [
    {
      kind: "NoOp",
      reason,
      evidence: [event.eventId],
      reevaluation: Cadence.Once(event.occurredAt),
      usefulWhen: { registryId: "operator.away", version: 1 },
    },
  ],
  trace: {
    reactorId: "worker-result-guard",
    reactorVersion: "1",
    branchPath: [event.type, "quarantine", reason],
    envInputs: [
      `now:${event.occurredAt}`,
      `authorityEnvelope:${stringField(state.authority, "authorityEnvelopeId") ?? "unavailable"}`,
    ],
    cadenceEvaluations: [],
  },
});

const workerResultGuard = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> | undefined => {
  if (asObject(event.payload)?.["workerResultVersion"] !== 1)
    return workerNoOp(state, event, "invalid worker receipt");
  if (
    stringField(event.payload, "commandId") !==
    stringField(state.pendingCommand, "commandId")
  )
    return workerNoOp(state, event, "unknown command");
  if (state.commandResult !== null) return observed(state, event, "dedup");
  if (env.now >= authorityFromState(state).expiresAt)
    return workerNoOp(state, event, "authority expired");
  if (
    stringField(event.payload, "workerEpisodeId") !== worker.workerEpisodeId ||
    worker.workerLeaseExpired
  )
    return workerNoOp(state, event, "stale worker lease");
  if (state.presence !== "away")
    return workerNoOp(state, event, "operator returned");
  return undefined;
};

const pinnedIdentity = (
  state: WalkingSkeletonSlice,
): ArtifactIdentityV1 | null =>
  isArtifactIdentityV1(state.artifactIdentity) ? state.artifactIdentity : null;

const withIdentityTrace = (
  decision: Decision<WalkingSkeletonSlice>,
  identity: ArtifactIdentityV1 | null,
  equippedEventId: string | null,
): Decision<WalkingSkeletonSlice> =>
  identity === null || equippedEventId === null
    ? decision
    : {
        ...decision,
        trace: {
          ...decision.trace,
          envInputs: [
            ...new Set([
              ...decision.trace.envInputs,
              ...artifactIdentityInputs(identity, equippedEventId),
            ]),
          ],
        },
      };

const artifactRefused = (
  state: WalkingSkeletonSlice,
  event: Event,
  type: ArtifactRefusalType,
  reason: string,
  options: Readonly<{
    pinned?: ArtifactIdentityV1 | null;
    observed?: ArtifactIdentityV1 | null;
    diagnostics?: readonly CompileDiagnostic[];
    drift?: readonly ArtifactDriftField[];
  }> = {},
): Decision<WalkingSkeletonSlice> => {
  const pin = options.pinned ?? pinnedIdentity(state);
  return {
    state:
      type === "UnknownScheduleRefused"
        ? state
        : {
            ...state,
            artifactIdentityBlocked: true,
            authority: null,
            pendingCommand: null,
            program: null,
            activeScheduleIds: [],
          },
    intents: [],
    schedules: [],
    continuation: Program.Emit(
      {
        schemaVersion: 1,
        type,
        occurredAt: event.occurredAt,
        actorId: event.actorId,
        workstreamId: event.workstreamId,
        ...(event.episodeId === undefined
          ? {}
          : { episodeId: event.episodeId }),
        ...(event.correlationId === undefined
          ? {}
          : { correlationId: event.correlationId }),
        causationId: event.eventId,
        payload: artifactRefusalPayload(
          reason,
          event.eventId,
          state.equippedEventId,
          pin,
          options.observed ?? null,
          options.diagnostics ?? [],
          options.drift ?? [],
        ) as unknown as JsonValue,
      },
      Program.Done(),
    ),
    trace: {
      reactorId: "artifact-identity",
      reactorVersion: "1",
      branchPath: [event.type, "refused", type, reason],
      envInputs: [
        "event",
        "equipped-artifact",
        "logged-enforcement-boundary",
        ...(pin === null || state.equippedEventId === null
          ? []
          : artifactIdentityInputs(pin, state.equippedEventId)),
      ],
      cadenceEvaluations: [],
    },
  };
};

const equipDecision = (
  state: WalkingSkeletonSlice,
  event: Event,
): Decision<WalkingSkeletonSlice> => {
  const payload = asObject(event.payload);
  const legacy =
    payload === undefined || !Object.hasOwn(payload, "payloadVersion");
  if (
    legacy &&
    (state.identityEnforcementEventId !== null || state.artifactIdentityBlocked)
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityUnavailable",
      "legacy equip after enforcement boundary",
    );
  if (
    !legacy &&
    (payload?.["payloadVersion"] !== 2 ||
      Object.keys(payload).sort().join(",") !==
        "artifactIdentity,graph,payloadVersion" ||
      !isArtifactIdentityV1(payload["artifactIdentity"]))
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "invalid v2 equip payload",
    );
  const pin = legacy
    ? null
    : (payload!["artifactIdentity"] as unknown as ArtifactIdentityV1);
  const graph = legacy ? event.payload : payload!["graph"]!;
  const environment =
    pin === null ? seiriEnvironment() : pin.compilationEnvironment;
  const compiled = compileArtifact(graph, environment);
  if (!compiled.ok)
    return artifactRefused(
      state,
      event,
      "ArtifactCompilationRefused",
      "compile diagnostics",
      {
        pinned: pin,
        diagnostics: compiled.diagnostics,
      },
    );
  const drift =
    pin === null ? [] : artifactIdentityDrift(pin, compiled.artifactIdentity);
  if (drift.length > 0)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityDrift",
      "equipped artifact differs from compilation",
      {
        pinned: pin,
        observed: compiled.artifactIdentity,
        drift,
      },
    );
  return withIdentityTrace(
    observed(
      {
        ...state,
        loadout: graph,
        artifactIdentity: pin as unknown as JsonValue,
        compilationEnvironment: environment as unknown as JsonValue,
        equippedEventId: event.eventId,
        artifactIdentityBlocked: false,
        authority: compiled.program.authorityEnvelope as unknown as JsonValue,
        ...(legacy
          ? {}
          : {
              workOrder: null,
              pendingCommand: null,
              program: null,
              activeScheduleIds: [],
            }),
      },
      event,
      "equipped",
    ),
    pin,
    event.eventId,
  );
};

/** Every compiled consumer, including stored authority/continuations, enters here. */
const withEquippedArtifact = (
  state: WalkingSkeletonSlice,
  event: Event,
  consume: (compiled: CompiledProgram) => Decision<WalkingSkeletonSlice>,
): Decision<WalkingSkeletonSlice> => {
  const pin = pinnedIdentity(state);
  if (state.artifactIdentity !== null && pin === null)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "invalid stored artifact identity",
    );
  if (pin !== null && state.equippedEventId === null)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityInvalid",
      "pinned artifact has no equip event reference",
    );
  if (
    state.loadout === null ||
    state.artifactIdentityBlocked ||
    (state.identityEnforcementEventId !== null && pin === null)
  )
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityUnavailable",
      state.loadout === null
        ? "no valid equip"
        : "explicit v2 re-equip required",
    );
  const compiled = compileArtifact(state.loadout, state.compilationEnvironment);
  if (!compiled.ok)
    return artifactRefused(
      state,
      event,
      "ArtifactCompilationRefused",
      "compile diagnostics",
      {
        diagnostics: compiled.diagnostics,
      },
    );
  const drift =
    pin === null ? [] : artifactIdentityDrift(pin, compiled.artifactIdentity);
  if (drift.length > 0)
    return artifactRefused(
      state,
      event,
      "ArtifactIdentityDrift",
      "pinned artifact differs from compilation",
      {
        observed: compiled.artifactIdentity,
        drift,
      },
    );
  return withIdentityTrace(
    consume(compiled.program),
    pin,
    state.equippedEventId,
  );
};

const predicateEnv = (env: KernelEnv): Omit<KernelEnv, "now"> => ({
  rngState: env.rngState,
  predicates: env.predicates,
  ...(env.policy === undefined ? {} : { policy: env.policy }),
});

const presenceDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<WalkingSkeletonSlice> => {
  const presence = stringField(event.payload, "presence");
  if (presence !== "away" && presence !== "returned")
    return observed(state, event, "invalid-presence");

  const nextState: WalkingSkeletonSlice = {
    ...state,
    presence,
    revocationEvents: [
      ...state.revocationEvents,
      event as unknown as JsonValue,
    ],
  };
  if (presence === "away") {
    const compiledCadence = cadenceFromCompiled(compiled);
    const cadence = compiledCadence.cadence as Cadence.T;
    const evaluated = evaluateCadence(
      cadence,
      selectPredicateState(nextState, worker),
      env,
      event,
    );
    if (evaluated.dueAt === null)
      throw new Error("away cadence did not produce a pulse");
    const schedules = [
      {
        scheduleId: compiledCadence.scheduleId,
        cadence,
        eventToEmit: draft(
          "CadencePulse",
          evaluated.dueAt,
          {
            scheduleId: compiledCadence.scheduleId,
          },
          undefined,
          event.eventId,
        ),
        cancelOn: compiledCadence.cancelOn,
      },
      {
        scheduleId: compiledCadence.queuedScheduleId,
        cadence: Cadence.Once(evaluated.dueAt + compiledCadence.queuedDelayMs),
        eventToEmit: draft(
          "CadencePulse",
          evaluated.dueAt + compiledCadence.queuedDelayMs,
          {
            scheduleId: compiledCadence.queuedScheduleId,
          },
          undefined,
          event.eventId,
        ),
        cancelOn: compiledCadence.cancelOn,
      },
    ] as const;
    return {
      state: {
        ...nextState,
        rngState: evaluated.rngState,
        activeScheduleIds: schedules.map((schedule) => schedule.scheduleId),
      },
      intents: [],
      schedules,
      trace: {
        reactorId: "seiri-cadence",
        reactorVersion: "1",
        branchPath: ["away", "scheduled"],
        envInputs: ["operatorPresence", "virtualTime"],
        cadenceEvaluations: [evaluated.trace],
      },
    };
  }

  const workOrder = workOrderFromState(nextState);
  const revoked = authorize(
    inspectIntent(workOrder),
    authorityFromState(state),
    {
      now: env.now,
      actorId: ACTOR,
      workstreamId: WORKSTREAM,
      episodeId: EPISODE,
      decisionIndex: 3,
      intentIndex: 0,
      evidence: [],
      revokedBy: revocationsFromState(nextState),
      state: selectPredicateState(nextState, worker),
      predicateEnv: predicateEnv(env),
    },
  );
  if (
    revoked.authorized ||
    revoked.refusal.payload.reason !== "authority revoked"
  )
    throw new Error("operator return did not revoke inspect authority");
  return {
    state: nextState,
    intents: [],
    schedules: [],
    trace: revoked.trace,
  };
};

const pulseDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<WalkingSkeletonSlice> => {
  const scheduleId = stringField(event.payload, "scheduleId");
  const compiledCadence = cadenceFromCompiled(compiled);
  if (scheduleId === compiledCadence.scheduleId) {
    const workOrder = compiled.workOrder;
    return {
      ...observed(
        {
          ...state,
          pulseSeen: true,
          workOrder: workOrder as unknown as JsonValue,
        },
        event,
        "work-order-ready",
      ),
      continuation: Program.Emit(
        draft(
          "WorkOrderEmitted",
          event.occurredAt,
          { workOrder: workOrder as unknown as JsonValue },
          event.eventId,
          event.eventId,
        ),
        Program.Done(),
      ),
    };
  }
  if (scheduleId !== compiledCadence.queuedScheduleId) {
    if (
      state.identityEnforcementEventId === null &&
      state.artifactIdentity === null
    )
      return observed(state, event, "unknown-schedule");
    return artifactRefused(
      state,
      event,
      "UnknownScheduleRefused",
      `unknown schedule: ${scheduleId ?? "unavailable"}`,
    );
  }

  const activationCondition = compiled.statechartGuards[0]?.activationCondition;
  if (activationCondition === undefined)
    throw new Error("compiled loadout lacks an activation guard");
  const guarded = guardQueuedPulse(
    selectPredicateState(state, worker),
    event,
    env,
    activationCondition,
    [compiledCadence.scheduleId, compiledCadence.queuedScheduleId],
  );
  return {
    state: {
      ...state,
      cancelledScheduleIds: guarded.cancelledScheduleIds,
    },
    intents: guarded.intents,
    schedules: guarded.schedules,
    trace: guarded.trace,
  };
};

const workOrderDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
  compiled: CompiledProgram,
): Decision<WalkingSkeletonSlice> => {
  const workOrder = workOrderFromValue(
    asObject(event.payload)?.["workOrder"] ?? null,
  );
  const verification = compiled.verificationPlan.find(
    (episode) => episode.required,
  );
  if (verification === undefined)
    throw new Error("compiled loadout lacks a required verification episode");
  const program = verificationProgram(
    workOrder,
    event.occurredAt,
    verification.subject,
  );
  const programDecision = decideProgram(
    program,
    selectPredicateState(state, worker),
    env,
  );
  const continuation = requiredContinuation(programDecision);
  const inspect = programDecision.intents[0];
  if (inspect?.kind !== "Act")
    throw new Error("verification program did not produce an inspect intent");
  const granted = authorize(inspect, authorityFromState(state), {
    now: env.now,
    actorId: ACTOR,
    workstreamId: WORKSTREAM,
    episodeId: EPISODE,
    decisionIndex: 1,
    intentIndex: 0,
    evidence: [],
    revokedBy: revocationsFromState(state),
    state: selectPredicateState(state, worker),
    predicateEnv: predicateEnv(env),
  });
  if (!granted.authorized)
    throw new Error(
      `inspection authorization failed: ${granted.refusal.payload.reason}`,
    );
  return {
    state: {
      ...state,
      workOrder: workOrder as unknown as JsonValue,
      authority: granted.authority as unknown as JsonValue,
      pendingCommand: granted.command as unknown as JsonValue,
      program: continuation as unknown as JsonValue,
    },
    intents: programDecision.intents,
    continuation,
    schedules: programDecision.schedules,
    trace: granted.trace,
  };
};

const deletionDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> => {
  const effect = stringField(event.payload, "effect") ?? "";
  const paths = stringArrayField(event.payload, "paths");
  const evidence = state.candidates.flatMap((candidate) => candidate.evidence);
  const deletion: ActIntent = { kind: "Act", effect, payload: { paths } };
  const refused = authorize(deletion, authorityFromState(state), {
    now: env.now,
    actorId: ACTOR,
    workstreamId: WORKSTREAM,
    episodeId: EPISODE,
    decisionIndex: 2,
    intentIndex: 0,
    evidence,
    revokedBy: revocationsFromState(state),
    state: selectPredicateState(state, worker),
    predicateEnv: predicateEnv(env),
  });
  if (refused.authorized) throw new Error("deletion unexpectedly authorized");
  return {
    state: {
      ...state,
      authorizationEvidence: evidence,
      deletionPaths: paths,
      refusalReason: refused.refusal.payload.reason,
    },
    intents: [],
    continuation: Program.Emit(
      linkedDraft(refused.refusal, expectedInspectCommandId, event.eventId),
      Program.Done(),
    ),
    schedules: [],
    trace: refused.trace,
  };
};

const episodeDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> => {
  const result = eventFromState(state.commandResult, "CommandResult");
  const continued = decideProgram(
    programFromState(state),
    selectPredicateState(state, worker),
    { ...env, now: result.occurredAt },
    result,
  );
  const continuation = requiredContinuation(continued);
  if (continuation.kind !== "Emit")
    throw new Error("verification continuation did not emit a request");
  const linkedContinuation = Program.Emit(
    linkedDraft(continuation.event, expectedInspectCommandId, event.eventId),
    continuation.next,
  );
  return {
    state: {
      ...state,
      program: linkedContinuation as unknown as JsonValue,
    },
    intents: continued.intents,
    continuation: linkedContinuation,
    schedules: continued.schedules,
    trace: continued.trace,
  };
};

const beaconSweepDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> => {
  const request = event.payload as unknown as BeaconSweepRequest & {
    decisionIndex: number;
    perceptionVersion?: number;
    perception?: PerceptionDeclaration;
    perceptionError?: string | null;
  };
  if (
    request.intent?.kind !== "Observe" ||
    request.intent.subject !== "control-beacons" ||
    !["public", "verifier"].includes(request.audience) ||
    !Number.isSafeInteger(request.staleAfterMs) ||
    request.staleAfterMs < 0 ||
    !Number.isSafeInteger(request.decisionIndex) ||
    request.decisionIndex < 0
  )
    throw new Error("invalid Beacon sweep request");
  const effect: ActIntent = {
    kind: "Act",
    effect: `observe.beacons.${request.audience}`,
    resource: "beaconSweeps",
    payload: { subject: request.intent.subject, audience: request.audience },
  };
  // Observation values are deliberately absent from this authority context.
  let authorization: AuthorizationResult = authorize(
    effect,
    request.authority,
    {
      now: env.now,
      actorId: event.actorId,
      workstreamId: event.workstreamId,
      ...(event.episodeId ? { episodeId: event.episodeId } : {}),
      decisionIndex: request.decisionIndex,
      intentIndex: 0,
      evidence: request.evidence,
      revokedBy: request.revokedBy,
      state: { presence: state.presence, policy: state.policy },
      predicateEnv: predicateEnv(env),
    },
  );
  if (authorization.authorized && request.perceptionVersion !== undefined) {
    const reason =
      request.perceptionVersion !== 1 || !request.perception
        ? "invalid Beacon perception version"
        : (request.perceptionError ??
          perceptionGate(
            request.perception,
            request.authority,
            request.audience,
          ));
    if (reason)
      authorization = refusePerception(event, request.authority, reason);
  }
  return {
    state: {
      ...state,
      beaconSweep: {
        requestEventId: event.eventId,
        staleAfterMs: request.staleAfterMs,
        authorization: authorization as unknown as JsonValue,
        ...(request.perceptionVersion === undefined
          ? {}
          : { perception: request.perception as unknown as JsonValue }),
      },
    },
    intents: authorization.authorized ? [request.intent] : [],
    schedules: [],
    trace: authorization.trace,
  };
};

const beaconObservedDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> => {
  const payload = event.payload as unknown as {
    sweptAt: number;
    observations: readonly SignalObservation[];
    commandId: string;
    groups?: PerceptionRead["groups"];
    keyEpoch?: number | null;
    perceptionVersion?: number;
  };
  const sweep = state.beaconSweep as unknown as {
    staleAfterMs: number;
    authorization: { authorized: boolean; command?: Command };
    perception?: PerceptionDeclaration;
  } | null;
  if (
    !sweep?.authorization.authorized ||
    payload.commandId !== sweep.authorization.command?.commandId ||
    payload.sweptAt !== event.occurredAt ||
    payload.sweptAt !== env.now ||
    !Array.isArray(payload.observations)
  )
    throw new Error("BeaconObserved lacks its authorized sweep or event time");
  if (sweep.perception) {
    if (
      payload.perceptionVersion !== 1 ||
      payload.groups === undefined ||
      payload.keyEpoch === undefined
    )
      throw new Error("BeaconObserved lacks its sense projection version");
    validatePerception(
      { observations: payload.observations, groups: payload.groups },
      sweep.perception,
      payload.keyEpoch,
    );
  }
  const cadenceEvaluations: string[] = [];
  const observations = payload.observations.map((observation): JudgedBeacon => {
    // Persist decoded perception, but bind it to the captured size on replay.
    const decoded =
      observation.size === null
        ? { status: "absent" }
        : (sweep.perception ? decodeSignalSize : decodeLegacySignalSize)(
            BigInt(observation.size),
          );
    if (canonicalStringify(decoded) !== canonicalStringify(observation.decoded))
      throw new Error(
        "BeaconObserved decoded fields differ from captured metadata",
      );
    let age = beaconAge(observation, env.now, sweep.staleAfterMs);
    if (age === "fresh" || age === "stale") {
      // The kernel clock is integer milliseconds: round the captured origin up
      // so a sub-ms remainder cannot fire the After cadence prematurely.
      const origin =
        observation.mtimeNs == null
          ? observation.mtimeMs!
          : Number((BigInt(observation.mtimeNs) + 999999n) / 1000000n);
      const evaluated = evaluateCadence(
        Cadence.After(sweep.staleAfterMs),
        selectPredicateState(state, worker),
        { ...env, now: origin },
        event,
      );
      cadenceEvaluations.push(evaluated.trace);
      age =
        evaluated.dueAt !== null && env.now >= evaluated.dueAt
          ? "stale"
          : "fresh";
    }
    return { ...observation, age };
  });
  return {
    state: {
      ...state,
      beaconObservations: observations,
      ...(sweep.perception
        ? { beaconGroups: payload.groups as unknown as JsonValue }
        : {}),
    },
    intents: [],
    schedules: [],
    trace: {
      reactorId: "beacon-observer",
      reactorVersion: "1",
      branchPath: ["BeaconObserved", ...observations.map(({ age }) => age)],
      envInputs: ["event.payload.observations", "event.occurredAt"],
      cadenceEvaluations,
    },
  };
};

const foldWalkingEvent = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
  compiled?: CompiledProgram,
): Decision<WalkingSkeletonSlice> => {
  switch (event.type) {
    case "BeaconSweepRequested":
      return beaconSweepDecision(state, worker, event, env);
    case "BeaconObserved":
      return beaconObservedDecision(state, worker, event, env);
    case "InspectionTaskCreated":
      return observed(state, event, "task-opened");
    case "OperatorPresenceChanged":
      return presenceDecision(state, worker, event, env, compiled!);
    case "CadencePulse":
      return pulseDecision(state, worker, event, env, compiled!);
    case "WorkOrderEmitted":
      return workOrderDecision(state, worker, event, env, compiled!);
    case "CommandRedispatchRequested":
      if (
        stringField(event.payload, "commandId") === undefined ||
        stringField(event.payload, "commandId") !==
          stringField(state.pendingCommand, "commandId")
      )
        return artifactRefused(
          state,
          event,
          "ArtifactIdentityInvalid",
          "recovery request does not name the stored command",
        );
      if (
        asObject(event.payload)?.["workerDispatchVersion"] === 1 &&
        (env.now >= authorityFromState(state).expiresAt ||
          state.presence !== "away")
      )
        return workerNoOp(
          state,
          event,
          env.now >= authorityFromState(state).expiresAt
            ? "authority expired"
            : "operator returned",
        );
      return observed(state, event, "redispatch-ready");
    case "CommandPersisted": {
      const command = asObject(event.payload)?.["command"] ?? null;
      const effect =
        command === null
          ? undefined
          : stringField(asObject(command)?.["intent"] ?? null, "effect");
      if (effect?.startsWith("observe.beacons."))
        return observed(state, event, "beacon-sweep-durable");
      return observed(
        {
          ...state,
          pendingCommand: command,
          persistedEffect: effect ?? null,
        },
        event,
        "command-durable",
      );
    }
    case "CommandRedispatched": {
      const commandId = stringField(event.payload, "commandId");
      return observed(
        {
          ...state,
          redispatchedCommandIds:
            commandId === undefined
              ? state.redispatchedCommandIds
              : [...state.redispatchedCommandIds, commandId],
        },
        event,
        "command-redispatched",
      );
    }
    case "WorkerResultObserved":
      return (
        workerResultGuard(state, worker, event, env) ??
        observed(state, event, "worker-result-admissible")
      );
    case "CommandResult": {
      if (event.workstreamId === "ws_beacon_control")
        return observed(state, event, "beacon-sweep-returned");
      if (asObject(event.payload)?.["workerResultVersion"] === 1) {
        const refusal = workerResultGuard(state, worker, event, env);
        if (refusal) return refusal;
      }
      const candidates = candidatesField(event.payload);
      const deletion: ActIntent = {
        kind: "Act",
        effect: "repo.delete",
        payload: { paths: candidates.map((candidate) => candidate.path) },
      };
      return {
        state: {
          ...state,
          candidates,
          commandResult: event as unknown as JsonValue,
          inspectionCompleted: true,
          deletionPaths: candidates.map((candidate) => candidate.path),
        },
        intents: [deletion],
        schedules: [],
        trace: {
          reactorId: "seiri-reactor",
          reactorVersion: "1",
          branchPath: ["CommandResult", "deletion-proposed"],
          envInputs: ["event.payload.candidates"],
          cadenceEvaluations: [],
        },
      };
    }
    case "DeletionAttempted":
      return deletionDecision(state, worker, event, env);
    case "CommandRefused":
      if (event.workstreamId === "ws_beacon_control")
        return observed(state, event, "beacon-sweep-refused");
      return {
        ...observed(
          {
            ...state,
            deletionRefused: true,
            refusalReason: stringField(event.payload, "reason") ?? null,
          },
          event,
          "episode-terminating",
        ),
        continuation: Program.Emit(
          draft(
            "EpisodeTerminated",
            event.occurredAt + 1,
            {
              continuation: "verification",
            },
            expectedInspectCommandId,
            event.eventId,
          ),
          Program.Done(),
        ),
      };
    case "EpisodeTerminated":
      return episodeDecision(state, worker, event, env);
    case "VerificationRequested":
      return {
        ...observed(state, event, "verification-dispatched"),
        intents: [{ kind: "Observe", subject: "candidates" }],
      };
    case "VerificationCompleted":
      return observed(
        {
          ...state,
          verified: asObject(event.payload)?.["accepted"] === true,
          verificationCompleted: true,
        },
        event,
        "verification-folded",
      );
    case "QueuedPulseNoOp":
      return observed(
        {
          ...state,
          queuedPulseNoOp: true,
          noOpEvidence: stringArrayField(event.payload, "evidence"),
        },
        event,
        "no-op-folded",
      );
    case "SchedulesCancelled":
      return observed(
        {
          ...state,
          cancelledScheduleIds: stringArrayField(event.payload, "scheduleIds"),
          activeScheduleIds: stringArrayField(
            event.payload,
            "activeScheduleIds",
          ),
        },
        event,
        "cancellation-folded",
      );
    default:
      return observed(state, event);
  }
};

const walkingDecision = (
  state: WalkingSkeletonSlice,
  worker: WorkerEpisodeSlice,
  event: Event,
  env: KernelEnv,
): Decision<WalkingSkeletonSlice> => {
  if (event.type === "ArtifactIdentityEnforcementStarted") {
    if (canonicalStringify(event.payload) !== '{"payloadVersion":1}')
      return artifactRefused(
        state,
        event,
        "ArtifactIdentityInvalid",
        "invalid enforcement boundary",
      );
    if (state.identityEnforcementEventId !== null)
      return observed(state, event, "already-enforced");
    return observed(
      {
        ...state,
        identityEnforcementEventId: event.eventId,
        ...(pinnedIdentity(state) === null
          ? { authority: null, pendingCommand: null, program: null }
          : {}),
      },
      event,
      "enforcement-started",
    );
  }
  if (event.type === "LoadoutEquipped") return equipDecision(state, event);
  if (isArtifactRefusalType(event.type))
    return observed(
      event.type === "UnknownScheduleRefused"
        ? state
        : {
            ...state,
            artifactIdentityBlocked: true,
            authority: null,
            pendingCommand: null,
            program: null,
            activeScheduleIds: [],
          },
      event,
      "refusal-recorded",
    );
  // Beacon authority is supplied by its explicit host request, not this loadout.
  const beaconResult =
    event.workstreamId === "ws_beacon_control" &&
    (event.type === "CommandResult" || event.type === "CommandRefused");
  const consumesProgram =
    !beaconResult &&
    [
      "OperatorPresenceChanged",
      "CadencePulse",
      "WorkOrderEmitted",
      "CommandResult",
      "WorkerResultObserved",
      "DeletionAttempted",
      "CommandRefused",
      "EpisodeTerminated",
      "VerificationRequested",
      "CommandRedispatchRequested",
    ].includes(event.type);
  return consumesProgram
    ? withEquippedArtifact(state, event, (compiled) =>
        foldWalkingEvent(state, worker, event, env, compiled),
      )
    : foldWalkingEvent(state, worker, event, env);
};

function foldWorkerEvent(
  state: WorkerEpisodeSlice,
  event: Event,
): SliceDecision<WorkerEpisodeSlice> {
  switch (event.type) {
    case "WorkerAttemptStarted":
      return observed(
        {
          ...state,
          workerEpisodeId:
            stringField(event.payload, "workerEpisodeId") ?? null,
          workerLeaseExpired: false,
        },
        event,
      );
    case "WorkerLeaseExpired":
      return stringField(event.payload, "workerEpisodeId") ===
        state.workerEpisodeId
        ? observed({ ...state, workerLeaseExpired: true }, event)
        : observed(state, event, "stale-lease");
    default:
      return observed(state, event);
  }
}

export const seiriReactor: Reactor<RuntimeState> = (runtime, event, env) => {
  const state = skeletonStateFromRuntime(runtime);
  const walking = selectWalkingSlice(state);
  // Retain the old validation order even in a feedback/verification workstream.
  if (walking.program !== null) programFromState(walking);
  switch (selectEventSlice(state, event)) {
    case "repair":
      return runtimeDecision(repairDecision(state.repair, event), (repair) => ({
        ...runtime,
        repair: json(repair),
      }));
    case "sourceChange":
      return runtimeDecision(
        sourceChangeDecision(selectSourceChangeSlice(state), event),
        (sourceChange) => ({ ...runtime, sourceChange }),
      );
    case "resident":
      return runtimeDecision(
        observed(
          foldResidentEvent(selectResidentSlice(state), event, env.predicates),
          event,
        ),
        (resident) => ({ ...runtime, resident: json(resident) }),
      );
    case "feedback":
      return runtimeDecision(
        feedbackDecision(selectFeedbackSlice(state), event),
        (feedback) => ({ ...runtime, feedback: json(feedback) }),
      );
    case "verification":
      return runtimeDecision(
        verificationDecision(selectVerificationSlice(state)!, event),
        (verification) => ({ ...runtime, verification: json(verification) }),
      );
    case "worker":
      return runtimeDecision(
        foldWorkerEvent(selectWorkerSlice(state), event),
        (worker) => ({ ...runtime, ...worker }),
      );
    case "walking":
      return runtimeDecision(
        walkingDecision(walking, selectWorkerSlice(state), event, env),
        (next) => ({ ...runtime, ...next }),
      );
  }
};

export const expectedInspectCommandId = commandId(WORKSTREAM, EPISODE, 1, 0);

// Independent-verification workstreams use the same typed reactor boundary.
export const VERIFICATION_HOST = "verification-host";
export interface MatrixEvaluation extends Evaluation {
  readonly provenance: {
    readonly kind: "host-admitted-verifier";
    readonly commandId: string;
    readonly inputHash: string;
  };
  readonly eventId: string;
  readonly episodeId: string;
  readonly subjectRevision: string;
  readonly stale: boolean;
}
export interface AcceptanceEvidenceRow {
  readonly criterion: AcceptanceCriterion;
  readonly status: "incomplete" | "verified" | "failed" | "stale";
  readonly evaluations: readonly MatrixEvaluation[];
}
export interface FindingRecord {
  readonly finding: VerificationFinding;
  readonly eventId: string;
  readonly episodeId: string;
  readonly subjectRevision: string;
  readonly status: "open" | "resolved" | "superseded";
}
export interface VerificationPending {
  readonly capsule: VerificationTask;
  readonly command: Command;
  readonly ordinal: number;
  readonly persisted: boolean;
  readonly attempts: readonly string[];
  readonly activeEpisode: string | null;
  readonly leaseExpiresAt: number;
  readonly leaseExpired: boolean;
}
export interface VerificationState {
  readonly episodeNamespace?: string;
  readonly workstreamId: string;
  readonly criteria: readonly AcceptanceCriterion[];
  readonly baseline: VerificationSubject | null;
  readonly subject: VerificationSubject | null;
  readonly rows: readonly AcceptanceEvidenceRow[];
  readonly evidence: readonly VerificationEvidence[];
  readonly findings: readonly FindingRecord[];
  readonly repairPlans: readonly {
    readonly findingId: string;
    readonly capsule: VerificationTask;
  }[];
  readonly implementerEpisodes: readonly string[];
  readonly episodeIds: readonly string[];
  readonly authority: AuthorityEnvelope | null;
  readonly revocations: readonly Event[];
  readonly pending: VerificationPending | null;
  readonly continuation: ExecutableProgramV1;
  readonly next:
    | "unopened"
    | "verify"
    | "repair"
    | "apply-repair"
    | "complete"
    | "attention";
  readonly proposal: RepairWorkerResult | null;
  readonly dispatchCount: number;
  readonly repairCount: number;
  readonly maxRepairs: number;
  readonly lastResultEventId: string | null;
  readonly refusedResults: readonly string[];
  readonly staleness: readonly {
    readonly eventId: string;
    readonly changedSurfaces: readonly string[];
    readonly criterionIds: readonly string[];
  }[];
}
export const initialVerificationState = (
  workstreamId: string,
): VerificationState => ({
  workstreamId,
  criteria: [],
  baseline: null,
  subject: null,
  rows: [],
  evidence: [],
  findings: [],
  repairPlans: [],
  implementerEpisodes: [],
  episodeIds: [],
  authority: null,
  revocations: [],
  pending: null,
  continuation: Program.Done(),
  next: "unopened",
  proposal: null,
  dispatchCount: 0,
  repairCount: 0,
  maxRepairs: 3,
  lastResultEventId: null,
  refusedResults: [],
  staleness: [],
});
const json = (value: unknown): JsonValue => value as JsonValue;
const env = (now: number) => ({ now, rngState: 17, predicates: {} });
const same = (a: unknown, b: unknown): boolean =>
  canonicalStringify(a) === canonicalStringify(b);
const requireState = (value: unknown, detail: string): void => {
  if (!value) throw new Error(`verification state: ${detail}`);
};
// EventEnvelope is deliberately open. Each branch checks the fields it consumes;
// model results cross the stricter, closed schema in parseEvidenceResult.
type VerificationPayload = {
  criteria: readonly AcceptanceCriterion[];
  baseline: VerificationSubject;
  subject: VerificationSubject;
  implementerEpisodeId: string;
  episodeNamespace?: string;
  maxRepairs: number;
  authority: AuthorityEnvelope;
  command: Command;
  commandId: string;
  workerEpisodeId: string;
  role: VerificationTask["role"];
  inputHash: string;
  leaseExpiresAt: number;
  mode: string;
  verificationResultVersion: number;
  result: string;
  value: EvidenceWorkerResult;
};

export function verificationAuthorization(
  state: VerificationState,
  at: number,
) {
  const pending = state.pending;
  if (!pending || !state.authority)
    throw new Error("verification lacks a pending authorized command");
  return authorize(pending.command.intent, state.authority, {
    now: at,
    actorId: VERIFICATION_HOST,
    workstreamId: state.workstreamId,
    episodeId: pending.command.episodeId!,
    decisionIndex: pending.ordinal,
    intentIndex: 0,
    evidence: ["pinned-subject", "baseline-witness"],
    revokedBy: state.revocations,
  });
}

/** The one-shot planning host shares the skeleton's authority decider owner. */
export function planRefutationAuthorization(
  authority: AuthorityEnvelope,
  subjectHash: string,
  episodeId: string,
  phase: "read" | "report",
  at: number,
) {
  return authorize(
    phase === "read"
      ? {
          kind: "Act",
          effect: "repo.read.plan-subject",
          payload: { subjectHash },
        }
      : { kind: "Act", effect: "report.emit", payload: {} },
    authority,
    {
      now: at,
      actorId: "entropy-reducer",
      workstreamId: "ws_plan_refuter",
      episodeId,
      decisionIndex: 0,
      intentIndex: phase === "read" ? 0 : 1,
      evidence: [],
      revokedBy: [],
    },
  );
}

/** Source-change hosts keep kernel decisions in the pure reactor boundary. */
export function sourceChangeAuthorization(
  ...args: Parameters<typeof authorize>
): ReturnType<typeof authorize> {
  return authorize(...args);
}

/** Harness adapters share the skeleton's authority decider owner. */
export function harnessAuthorization(
  authority: AuthorityEnvelope,
  effect: string,
  at: number,
) {
  return authorize({ kind: "Act", effect, payload: {} }, authority, {
    now: at,
    actorId: "contributor-hook",
    workstreamId: "contributor-session",
    decisionIndex: 0,
    intentIndex: 0,
    evidence: ["resolved-worktree"],
    revokedBy: [],
  });
}

function dispatch(state: VerificationState): VerificationState {
  requireState(
    !state.pending &&
      state.subject &&
      state.continuation.kind === "Done" &&
      ["verify", "repair"].includes(state.next),
    "dispatch phase",
  );
  const ordinal = state.dispatchCount + 1;
  const finding =
    state.next === "repair"
      ? (state.findings.find(
          (record) =>
            record.status === "open" && record.finding.severity === "blocking",
        )?.finding ?? null)
      : null;
  requireState(state.next !== "repair" || finding, "repair finding");
  const criteria = finding
    ? state.criteria.filter(
        (criterion) => criterion.criterionId === finding.criterionId,
      )
    : state.rows
        .filter((row) => row.status !== "verified")
        .map((row) => row.criterion);
  const capsule = compileVerificationTask(
    `verification_${ordinal}`,
    criteria,
    state.subject!,
    finding,
  );
  const episodeId = `${state.episodeNamespace ? `${state.episodeNamespace}_` : ""}ep_${capsule.role}_${ordinal}`;
  const command: Command = {
    commandId: commandId(state.workstreamId, episodeId, ordinal, 0),
    episodeId,
    workstreamId: state.workstreamId,
    intent: {
      kind: "Act",
      effect: capsule.workOrder.allowedOperations[0]!,
      resource: "episodes",
      payload: json({ capsule }),
    },
  };
  const continuation = Program.Invoke(command.commandId, command.intent, {
    completed: Program.Emit(
      {
        schemaVersion: 1,
        type: "VerificationContinuation",
        actorId: VERIFICATION_HOST,
        workstreamId: state.workstreamId,
        occurredAt: 0,
        correlationId: command.commandId,
        payload: { commandId: command.commandId },
      },
      Program.Done(),
    ),
  });
  // The kernel emits the dispatch intent. The host persists it before invoking a transport.
  const decision = decideProgram(continuation, json(state), env(0));
  requireState(decision.intents.length === 1, "kernel dispatch intent");
  return {
    ...state,
    dispatchCount: ordinal,
    continuation,
    pending: {
      capsule,
      command,
      ordinal,
      persisted: false,
      attempts: [],
      activeEpisode: null,
      leaseExpiresAt: 0,
      leaseExpired: false,
    },
  };
}

/** Pure event-loop fold. Worker prose and implementer events have no acceptance path. */
function foldVerificationEvent(
  state: VerificationState,
  event: Event,
): VerificationState {
  if (event.workstreamId !== state.workstreamId) return state;
  if (state.authority?.revocationEventTypes.includes(event.type))
    return { ...state, revocations: [...state.revocations, event] };
  if (event.actorId !== VERIFICATION_HOST) return state;
  const value = event.payload as unknown as VerificationPayload;
  switch (event.type) {
    case "VerificationOpened": {
      requireState(state.next === "unopened", "workstream already opened");
      const criteria = (value.criteria as AcceptanceCriterion[]).map(
        copyCriterion,
      );
      const baseline = copySubject(value.baseline as VerificationSubject);
      const subject = copySubject(value.subject as VerificationSubject);
      compileVerificationTask("opening", criteria, subject);
      requireState(
        baseline.repo === subject.repo &&
          baseline.baseCommit === subject.baseCommit &&
          baseline.revision === subject.baseCommit,
        "baseline identity",
      );
      requireState(
        typeof value.implementerEpisodeId === "string" &&
          value.implementerEpisodeId.length > 0 &&
          Number.isSafeInteger(value.maxRepairs) &&
          value.maxRepairs >= 0 &&
          value.maxRepairs <= 10,
        "opening policy",
      );
      requireState(
        baseline.evidence.length > 0 &&
          criteria.every((criterion) =>
            baseline.evidence.some(
              (item) => item.criterionId === criterion.criterionId,
            ),
          ),
        "baseline witness coverage",
      );
      requireState(
        value.episodeNamespace === undefined ||
          /^[a-zA-Z0-9_-]+$/u.test(value.episodeNamespace),
        "episode namespace",
      );
      return {
        ...state,
        ...(value.episodeNamespace
          ? { episodeNamespace: value.episodeNamespace }
          : {}),
        criteria,
        baseline,
        subject,
        authority: value.authority as AuthorityEnvelope,
        maxRepairs: value.maxRepairs,
        implementerEpisodes: [value.implementerEpisodeId],
        episodeIds: [value.implementerEpisodeId],
        rows: criteria.map((criterion) => ({
          criterion,
          status: "incomplete",
          evaluations: [],
        })),
        evidence: subject.evidence,
        next: "verify",
      };
    }
    case "VerificationDispatchRequested":
      return dispatch(state);
    case "CommandPersisted": {
      const pending = state.pending;
      if (!pending || value.command?.commandId !== pending.command.commandId)
        return state;
      requireState(
        same(value.command, pending.command),
        "persisted compilation drift",
      );
      requireState(
        verificationAuthorization(state, event.occurredAt).authorized,
        "persist without authority",
      );
      return { ...state, pending: { ...pending, persisted: true } };
    }
    case "WorkerAttemptStarted": {
      const pending = state.pending;
      if (
        !pending ||
        !pending.persisted ||
        value.commandId !== pending.command.commandId
      )
        return state;
      requireState(
        !state.episodeIds.includes(value.workerEpisodeId) &&
          typeof value.workerEpisodeId === "string" &&
          value.role === pending.capsule.role &&
          value.inputHash === pending.capsule.inputHash &&
          typeof value.leaseExpiresAt === "number" &&
          value.leaseExpiresAt > event.occurredAt,
        "fresh physical episode",
      );
      requireState(
        pending.activeEpisode === null ||
          pending.leaseExpired ||
          event.occurredAt >= pending.leaseExpiresAt ||
          value.mode === "cached-result-query",
        "prior episode still leased",
      );
      return {
        ...state,
        episodeIds: [...state.episodeIds, value.workerEpisodeId],
        pending: {
          ...pending,
          attempts: [...pending.attempts, value.workerEpisodeId],
          activeEpisode: value.workerEpisodeId,
          leaseExpiresAt: value.leaseExpiresAt,
          leaseExpired: false,
        },
      };
    }
    case "WorkerHeartbeat": {
      const pending = state.pending;
      if (
        !pending ||
        value.workerEpisodeId !== pending.activeEpisode ||
        pending.leaseExpired ||
        event.occurredAt >= pending.leaseExpiresAt
      )
        return state;
      return {
        ...state,
        pending: { ...pending, leaseExpiresAt: value.leaseExpiresAt },
      };
    }
    case "WorkerLeaseExpired": {
      const pending = state.pending;
      if (
        !pending ||
        value.workerEpisodeId !== pending.activeEpisode ||
        event.occurredAt < pending.leaseExpiresAt
      )
        return state;
      return { ...state, pending: { ...pending, leaseExpired: true } };
    }
    case "CommandResult": {
      const pending = state.pending;
      if (
        !pending ||
        !pending.persisted ||
        value.commandId !== pending.command.commandId ||
        value.verificationResultVersion !== 1
      )
        return state;
      let result: EvidenceWorkerResult;
      try {
        requireState(
          value.workerEpisodeId === pending.activeEpisode &&
            !pending.leaseExpired &&
            event.occurredAt < pending.leaseExpiresAt &&
            pending.attempts.includes(value.value?.envelope?.episodeId) &&
            !state.implementerEpisodes.includes(
              value.value?.envelope?.episodeId,
            ),
          "result episode or lease",
        );
        requireState(
          verificationAuthorization(state, event.occurredAt).authorized,
          "result authority",
        );
        assertVerificationTask(pending.capsule);
        requireState(
          pending.capsule.subject.revision === state.subject?.revision,
          "result subject drift",
        );
        result = parseEvidenceResult(value.value, {
          command: pending.command,
          workOrder: pending.capsule.workOrder,
          capsule: pending.capsule,
          episodeId: value.value.envelope.episodeId,
        });
        requireState(
          result.envelope.status === "completed" &&
            value.result === "completed",
          "incomplete result",
        );
      } catch {
        return {
          ...state,
          refusedResults: [...state.refusedResults, event.eventId],
        };
      }
      const step = decideProgram(
        state.continuation,
        json(state),
        env(event.occurredAt),
        event,
      );
      requireState(step.continuation?.kind === "Emit", "result continuation");
      const common = {
        ...state,
        pending: null,
        lastResultEventId: event.eventId,
        continuation: step.continuation!,
      };
      if (result.kind === "repair")
        return {
          ...common,
          next: result.envelope.requiresHuman ? "attention" : "apply-repair",
          proposal: result,
        };
      const rows = state.rows.map((row): AcceptanceEvidenceRow => {
        const evaluation = result.evaluations.find(
          (item) => item.criterionId === row.criterion.criterionId,
        );
        return evaluation
          ? {
              criterion: row.criterion,
              status:
                evaluation.verdict === "pass"
                  ? "verified"
                  : evaluation.verdict === "fail"
                    ? "failed"
                    : "incomplete",
              evaluations: [
                ...row.evaluations,
                {
                  ...evaluation,
                  provenance: {
                    kind: "host-admitted-verifier",
                    commandId: pending.command.commandId,
                    inputHash: pending.capsule.inputHash,
                  },
                  eventId: event.eventId,
                  episodeId: result.envelope.episodeId,
                  subjectRevision: result.subjectRevision,
                  stale: false,
                },
              ],
            }
          : row;
      });
      const findingRecords: FindingRecord[] = result.findings.map(
        (finding) => ({
          finding,
          eventId: event.eventId,
          episodeId: result.envelope.episodeId,
          subjectRevision: result.subjectRevision,
          status: "open",
        }),
      );
      // A subsequent conclusive verifier assessment supersedes findings for its criteria.
      const assessed = result.evaluations
        .filter((item) => item.verdict !== "unverified")
        .map((item) => item.criterionId);
      const findings = [
        ...state.findings.map((record): FindingRecord =>
          assessed.includes(record.finding.criterionId)
            ? {
                ...record,
                status:
                  result.evaluations.find(
                    (item) => item.criterionId === record.finding.criterionId,
                  )?.verdict === "pass"
                    ? "resolved"
                    : "superseded",
              }
            : record,
        ),
        ...findingRecords,
      ];
      const repairPlans = result.findings
        .filter((finding) => finding.severity === "blocking")
        .map((finding) => ({
          findingId: finding.findingId,
          capsule: compileVerificationTask(
            `repair_${state.dispatchCount}_${finding.findingId}`,
            state.criteria.filter(
              (criterion) => criterion.criterionId === finding.criterionId,
            ),
            state.subject!,
            finding,
          ),
        }));
      return {
        ...common,
        rows,
        findings,
        repairPlans: [...state.repairPlans, ...repairPlans],
        next: result.envelope.requiresHuman
          ? "attention"
          : rows.every((row) => row.status === "verified")
            ? "complete"
            : repairPlans.length > 0 && state.repairCount < state.maxRepairs
              ? "repair"
              : "attention",
      };
    }
    case "VerificationContinuation": {
      requireState(
        state.continuation.kind === "Emit" &&
          event.correlationId === state.continuation.event.correlationId &&
          same(event.payload, state.continuation.event.payload),
        "continuation identity",
      );
      const step = decideProgram(
        state.continuation,
        json(state),
        env(event.occurredAt),
      );
      requireState(step.emitted.length === 1, "kernel continuation emission");
      return { ...state, continuation: step.continuation! };
    }
    case "VerificationSubjectSubmitted": {
      requireState(
        state.next === "apply-repair" &&
          state.proposal &&
          state.subject &&
          state.continuation.kind === "Done",
        "repair application phase",
      );
      const subject = copySubject(value.subject as VerificationSubject);
      requireState(
        subject.repo === state.subject!.repo &&
          subject.baseCommit === state.subject!.baseCommit &&
          subject.revision !== state.subject!.revision,
        "repair revision identity",
      );
      const expected = state.subject!.files.map(
        (file) =>
          state.proposal!.replacements.find(
            (replacement) => replacement.path === file.path,
          ) ?? file,
      );
      requireState(
        same(subject.files, expected),
        "applied repair differs from proposal",
      );
      compileVerificationTask("repaired", state.criteria, subject);
      const changedSurfaces = changedVerificationSurfaces(
        state.subject!,
        subject,
      );
      requireState(changedSurfaces.length > 0, "repair must change source");
      const affected = affectedVerificationCriteria(
        state.criteria,
        changedSurfaces,
      );
      const rows = state.rows.map((row): AcceptanceEvidenceRow =>
        affected.includes(row.criterion.criterionId)
          ? {
              ...row,
              status: row.evaluations.length > 0 ? "stale" : "incomplete",
              evaluations: row.evaluations.map((evaluation) => ({
                ...evaluation,
                stale: true,
              })),
            }
          : row,
      );
      return {
        ...state,
        subject,
        rows,
        next: "verify",
        proposal: null,
        repairCount: state.repairCount + 1,
        implementerEpisodes: [
          ...state.implementerEpisodes,
          state.proposal!.envelope.episodeId,
        ],
        evidence: [...state.evidence, ...subject.evidence],
        staleness: [
          ...state.staleness,
          { eventId: event.eventId, changedSurfaces, criterionIds: affected },
        ],
      };
    }
    default:
      return state;
  }
}

export const initialVerificationRuntime = (
  workstreamId: string,
): RuntimeState => ({
  ...initialState(),
  verification: json(initialVerificationState(workstreamId)),
});
export const verificationStateFromRuntime = (
  state: RuntimeState,
): VerificationState => {
  if (state.verification === undefined)
    throw new Error("runtime lacks a verification workstream");
  const verification = state.verification as unknown as VerificationState;
  return {
    ...verification,
    continuation: persistedContinuation(
      verification?.continuation,
      "verification continuation",
    ),
  };
};
function verificationDecision(
  state: VerificationState,
  event: Event,
): SliceDecision<VerificationState> {
  const before = {
    ...state,
    continuation: persistedContinuation(
      state?.continuation,
      "verification continuation",
    ),
  };
  const next = foldVerificationEvent(before, event);
  return {
    state: next,
    intents:
      before.pending === null && next.pending !== null
        ? [next.pending.command.intent]
        : [],
    continuation: next.continuation,
    schedules: [],
    trace: {
      reactorId: "independent-verification",
      reactorVersion: "1",
      branchPath: [
        event.type,
        next.next,
        next.refusedResults.length > before.refusedResults.length
          ? "refused-result"
          : "folded",
      ],
      envInputs: [
        "event.actorId",
        "event.workstreamId",
        "event.payload",
        "event.occurredAt",
      ],
      cadenceEvaluations: [],
    },
  };
}

export interface FeedbackRuntimeState {
  readonly workstreamId: string;
  readonly program: CompiledFeedback;
  readonly workOrder: WorkOrder;
  readonly subject: string;
  readonly authority: AuthorityEnvelope;
  readonly policy: CorrectionState;
  readonly pending: Command | null;
  readonly persisted: boolean;
  readonly result: JsonValue | null;
}
export function feedbackStateFromRuntime(
  state: RuntimeState,
): FeedbackRuntimeState {
  if (state.feedback === undefined)
    throw new Error("feedback workstream not opened");
  return state.feedback as unknown as FeedbackRuntimeState;
}
/** Feedback shares the single kernel decider. All I/O remains in its host. */
function feedbackDecision(
  state: FeedbackRuntimeState | undefined,
  event: Event,
): SliceDecision<FeedbackRuntimeState | undefined> {
  if (event.type === "FeedbackAuditOpened") {
    if (
      state !== undefined ||
      event.actorId !== "feedback-host" ||
      !event.workstreamId
    )
      throw new Error("feedback opening refused");
    const value = event.payload as unknown as {
      program: CompiledFeedback;
      workOrder: WorkOrder;
      subject: string;
      authority: AuthorityEnvelope;
    };
    assertCompiledFeedback(value.program);
    if (
      !same(
        value.workOrder,
        compileFeedbackAudit(
          value.program,
          value.workOrder.repo,
          value.workOrder.baseCommit,
          value.subject,
        ),
      )
    )
      throw new Error("feedback work order drift");
    const next: FeedbackRuntimeState = {
      ...value,
      workstreamId: event.workstreamId,
      pending: null,
      persisted: false,
      result: null,
      policy: {
        allowedEffects: value.authority.allowedEffects,
        destructiveEffects: ["repo.write", "repo.delete", "publish"],
        scopeExpansionAllowed: false,
        preserveEvidence: true,
        diagnosisRequired: false,
        corrections: [],
      },
    };
    return observed(next, event, "feedback-opened");
  }
  if (state === undefined) throw new Error("feedback workstream not opened");
  const before = state;
  if (event.workstreamId !== before.workstreamId)
    return observed(state, event, "feedback-outside-workstream");
  assertCompiledFeedback(before.program);
  if (
    event.actorId === "operator" &&
    SEMANTIC_CORRECTIONS.some((type) => type === event.type)
  ) {
    const policy = applyFeedbackCorrection(
      before.program,
      before.policy,
      event,
    );
    const decision = observed(
      { ...before, policy },
      event,
      "feedback-correction",
    );
    return policy === before.policy
      ? decision
      : {
          ...decision,
          continuation: Program.Emit(
            {
              schemaVersion: 1,
              type: "FeedbackDiagnosisRequested",
              actorId: "feedback-host",
              occurredAt: event.occurredAt,
              workstreamId: event.workstreamId,
              causationId: event.eventId,
              payload: {
                correctionEventId: event.eventId,
                policyHash: before.program.policyHash,
              },
            },
            Program.Done(),
          ),
        };
  }
  if (event.actorId !== "feedback-host")
    return observed(state, event, "feedback-untrusted-event");
  if (event.type === "FeedbackAuditExecutionRequested") {
    if (
      !before.pending ||
      !before.persisted ||
      before.result ||
      before.policy.diagnosisRequired ||
      !before.policy.allowedEffects.includes("feedback.audit")
    )
      return observed(state, event, "feedback-execution-refused");
    const grant = authorize(before.pending.intent, before.authority, {
      now: event.occurredAt,
      actorId: "feedback-host",
      workstreamId: event.workstreamId!,
      episodeId: "ep_feedback_executor",
      decisionIndex: 1,
      intentIndex: 0,
      evidence: ["feedback-policy", "pinned-source"],
      revokedBy: [],
    });
    return observed(
      state,
      event,
      grant.authorized && same(grant.command, before.pending)
        ? "feedback-execution-ready"
        : "feedback-execution-refused",
    );
  }
  if (event.type === "FeedbackAuditRequested") {
    if (
      before.pending ||
      before.result ||
      before.policy.diagnosisRequired ||
      !before.policy.allowedEffects.includes("feedback.audit")
    )
      return observed(state, event, "feedback-audit-refused");
    const intent: ActIntent = {
      kind: "Act",
      effect: "feedback.audit",
      resource: "audits",
      payload: json({
        workOrder: before.workOrder,
        policyHash: before.program.policyHash,
        subject: before.subject,
      }),
    };
    const grant = authorize(intent, before.authority, {
      now: event.occurredAt,
      actorId: "feedback-host",
      workstreamId: event.workstreamId!,
      episodeId: "ep_feedback_executor",
      decisionIndex: 1,
      intentIndex: 0,
      evidence: ["feedback-policy", "pinned-source"],
      revokedBy: [],
    });
    if (!grant.authorized)
      return {
        ...observed(state, event, "feedback-authority-refused"),
        continuation: Program.Emit(grant.refusal, Program.Done()),
      };
    const program = Program.Invoke(grant.command.commandId, intent, {
      completed: Program.Done(),
    });
    const dispatched = decideProgram(program, {}, env(event.occurredAt));
    return {
      ...observed(
        { ...before, pending: grant.command },
        event,
        "feedback-audit-dispatched",
      ),
      intents: dispatched.intents,
      continuation: program,
    };
  }
  if (event.type === "CommandPersisted") {
    const command = (event.payload as unknown as { command: Command }).command;
    if (!before.pending || before.result || !same(command, before.pending))
      throw new Error("feedback command persistence mismatch");
    return observed(
      { ...before, persisted: true },
      event,
      "feedback-command-persisted",
    );
  }
  if (event.type === "CommandResult") {
    const result = event.payload as unknown as {
      commandId: string;
      subject: string;
      policyHash: string;
      report: JsonValue;
    };
    if (
      !before.persisted ||
      !before.pending ||
      before.result ||
      result.commandId !== before.pending.commandId ||
      result.subject !== before.subject ||
      result.policyHash !== before.program.policyHash ||
      result.report === undefined
    )
      throw new Error("feedback result mismatch");
    return {
      ...observed(
        { ...before, result: result.report },
        event,
        "feedback-audit-executed",
      ),
      continuation: Program.Done(),
    };
  }
  return observed(state, event, "feedback-observed");
}

/** Repair orchestration uses the same kernel executable subset and owner. */
function repairDecision(
  previous: RepairState | undefined,
  event: Event,
): SliceDecision<RepairState> {
  if (event.actorId !== REPAIR_HOST)
    throw new Error("repair event requires host actor");
  const p = event.payload as unknown as Record<string, any>;
  const check = (condition: unknown, detail: string) => {
    if (!condition) throw new Error(`repair state: ${detail}`);
  };
  let state: RepairState;
  if (event.type === "RepairOpened") {
    check(!previous, "already opened");
    const original = p.original as RepairOriginal;
    const contract = repairContract(original.workOrder);
    const limit = original.roundLimit ?? 2;
    check(Number.isSafeInteger(limit) && limit >= 0, "round limit");
    check(original.surfaces.length && original.tests.length, "original scope");
    const subject = copySubject(p.subject as VerificationSubject);
    const baseline = copySubject(p.baseline as VerificationSubject);
    compileVerificationTask("repair_preflight", original.criteria, subject);
    check(
      subject.snapshot &&
        repairEqual(subject.snapshot.contract, contract) &&
        repairEqual(subject.snapshot.tests, original.tests) &&
        subject.baseCommit === original.workOrder.baseCommit,
      "original contract, tests or base mismatch",
    );
    check(
      baseline.revision === original.workOrder.baseCommit &&
        baseline.baseCommit === subject.baseCommit &&
        baseline.repo === subject.repo,
      "baseline mismatch",
    );
    state = {
      workstreamId: event.workstreamId,
      original,
      grants: p.grants as RepairGrants,
      baseline,
      subject,
      currentCommit: subject.revision,
      round: 0,
      continuation: Program.Done(),
      pending: null,
      emission: null,
      order: null,
      finding: null,
      verified: false,
      status: "running",
      reason: null,
    };
    const decoded = decodeContinuation(p.continuation);
    check(
      decoded.ok &&
        repairEqual(
          decoded.ok ? decoded.value : null,
          repairVerificationProgram(state),
        ),
      "opening continuation mismatch",
    );
    state = { ...state, continuation: repairVerificationProgram(state) };
  } else {
    check(
      previous && previous.workstreamId === event.workstreamId,
      "workstream mismatch",
    );
    state = previous!;
    check(state.status === "running", "terminal workstream");
    const step = (input?: Event) => {
      const decision = decideProgram(
        state.continuation,
        json(state),
        {
          now: event.occurredAt,
          rngState: 0,
          predicates: {
            "repair.verified": { 1: () => state.verified },
            "repair.remaining": {
              1: () => state.round < (state.original.roundLimit ?? 2),
            },
          },
        },
        input,
      );
      state = {
        ...state,
        continuation: decision.continuation,
        emission: decision.emitted[0]
          ? {
              ...decision.emitted[0],
              payload: { round: state.round, finding: json(state.finding) },
            }
          : null,
      };
      if (state.emission?.type === "RepairDerived") {
        const derivation = deriveRepairOrder(
          state.finding!,
          { ...state.original, subject: state.subject, round: state.round },
          state.grants,
        );
        const continuation =
          derivation.kind === "derived"
            ? repairRoundProgram({
                ...state,
                order: derivation.order,
                round: derivation.order.round,
              })
            : Program.Done();
        state = {
          ...state,
          emission: {
            ...state.emission,
            payload: {
              ...(state.emission.payload as Record<string, JsonValue>),
              derivation: json(derivation),
              continuation: json(continuation),
            },
          },
        };
      }
      return decision;
    };
    if (event.type === "RepairTick") {
      check(!state.pending && !state.emission, "tick with pending effect");
      const decision = step();
      // Intents are offered to the host; only CommandPersisted admits ownership.
      return { ...decision, state };
    } else if (event.type === "RepairCommandPersisted") {
      check(!state.pending && !state.emission, "duplicate pending command");
      const decision = step();
      const command = p.command as Command;
      check(
        decision.intents.length === 1 &&
          repairEqual(decision.intents[0], command.intent),
        "command not selected by program",
      );
      const kind = (command.intent.payload as { kind: "write" | "verify" })
        .kind;
      check(
        repairEqual(command, repairCommand(state, kind)),
        "command identity",
      );
      state = { ...state, pending: command };
    } else if (event.type === "RepairCommandResult") {
      check(
        state.pending && p.commandId === state.pending.commandId,
        "result without pending command",
      );
      if (state.pending!.intent.effect === "repo.write") {
        check(
          p.result === "accepted" && state.order,
          "repair ownership result",
        );
      } else {
        check(p.result === "completed", "verification result kind");
        const capsule = p.capsule as VerificationTask;
        assertVerificationTask(capsule);
        check(
          capsule.role === "verifier" &&
            capsule.subject.revision === state.currentCommit &&
            capsule.subject.baseCommit ===
              state.original.workOrder.baseCommit &&
            capsule.subject.repo === state.subject.repo &&
            repairEqual(capsule.criteria, state.original.criteria) &&
            repairEqual(
              capsule.subject.snapshot?.contract,
              repairContract(state.original.workOrder),
            ) &&
            repairEqual(capsule.subject.snapshot?.tests, state.original.tests),
          "re-verification changed original contract",
        );
        const result = parseEvidenceResult(p.value, {
          command: p.verifierCommand as Command,
          workOrder: capsule.workOrder,
          capsule,
          episodeId: p.value?.envelope?.episodeId,
        });
        check(
          result.kind === "verification" &&
            result.envelope.status === "completed",
          "unusable verification",
        );
        if (result.kind !== "verification")
          throw new Error("repair requires verification");
        const verified =
          !result.envelope.requiresHuman &&
          result.evaluations.length === state.original.criteria.length &&
          result.evaluations.every((e) => e.verdict === "pass");
        const finding =
          result.findings.find((f) => f.severity === "blocking") ?? null;
        state = { ...state, subject: capsule.subject, verified, finding };
        if (!verified && (!finding || result.envelope.requiresHuman)) {
          state = {
            ...state,
            pending: null,
            continuation: Program.Done(),
            emission: {
              schemaVersion: 1,
              type: "NeedsHuman",
              actorId: REPAIR_HOST,
              workstreamId: state.workstreamId,
              occurredAt: 0,
              payload: {
                reason: "verification needs human attention",
                offending: finding?.findingId ?? "unverified",
              },
            },
          };
          return observed(state, event);
        }
      }
      step({ ...event, type: "CommandResult" });
      state = { ...state, pending: null };
    } else if (event.type === "SourceChangeObserved") {
      check(state.order && !state.pending, "source observation without repair");
      const observation = decodeSourceObservation(p.observation);
      check(
        Array.isArray(p.tests) &&
          repairEqual(
            p.tests.map((test: unknown) => decodeFocusedTest(test).command),
            state.order!.tests.map((test) => test.command),
          ),
        "repair reproduction commands mismatch",
      );
      const command = repairCommand(state, "write");
      check(
        event.correlationId === command.commandId &&
          observation.workOrderId === state.order!.workOrder.workOrderId &&
          observation.commit !== state.order!.executionBaseCommit,
        "source observation identity",
      );
      const before = state.continuation;
      step(event);
      check(
        !repairEqual(before, state.continuation),
        "source observation not awaited",
      );
      state = { ...state, currentCommit: observation.commit };
    } else if (event.type === "NeedsHuman") {
      if (state.emission)
        check(
          state.emission.type === event.type &&
            repairEqual(state.emission.payload, event.payload),
          "human disposition mismatch",
        );
      check(
        typeof p.reason === "string" && typeof p.offending === "string",
        "human disposition fields",
      );
      state = {
        ...state,
        status: "needs-human",
        reason: `${p.reason}: ${p.offending}`,
        continuation: Program.Done(),
        pending: null,
        emission: null,
      };
    } else {
      check(
        state.emission?.type === event.type &&
          repairEqual(state.emission.payload, event.payload),
        "program emission mismatch",
      );
      state = { ...state, emission: null };
      if (event.type === "RepairDerived") {
        const derived = deriveRepairOrder(
          state.finding!,
          { ...state.original, subject: state.subject, round: state.round },
          state.grants,
        );
        check(repairEqual(derived, p.derivation), "derived order drift");
        if (derived.kind === "NeedsHuman") {
          state = {
            ...state,
            continuation: Program.Done(),
            emission: {
              schemaVersion: 1,
              type: "NeedsHuman",
              actorId: REPAIR_HOST,
              workstreamId: state.workstreamId,
              occurredAt: 0,
              payload: { reason: derived.reason, offending: derived.offending },
            },
          };
        } else {
          state = {
            ...state,
            order: derived.order,
            round: derived.order.round,
            verified: false,
          };
          const decoded = decodeContinuation(p.continuation);
          check(
            decoded.ok &&
              repairEqual(
                decoded.ok ? decoded.value : null,
                repairRoundProgram(state),
              ),
            "derived continuation drift",
          );
          state = {
            ...state,
            continuation: decoded.ok ? decoded.value : Program.Done(),
          };
        }
      } else if (
        event.type === "RepairCompleted" ||
        event.type === "RepairExhausted"
      ) {
        check(
          event.type !== "RepairExhausted" || state.finding,
          "exhaustion lacks last finding",
        );
        state = {
          ...state,
          status: event.type === "RepairCompleted" ? "complete" : "exhausted",
          continuation: Program.Done(),
        };
      } else throw new Error(`unknown repair event ${event.type}`);
    }
  }
  return observed(state, event);
}

import {
  canonicalStringify,
  copyFinding,
  fnv1a64,
  repositoryPath,
  type AcceptanceCriterion,
  type AuthorityGrant,
  type NamedVerificationTest,
  type VerificationFinding,
  type VerificationEvidence,
  type VerificationSubject,
  type WorktreeVerificationContract,
} from "@dotln/compiler";
import {
  Program,
  type AuthorityEnvelope,
  type Command,
  type EventDraft,
  type ExecutableProgramV1,
  type JsonValue,
  type WorkOrder,
} from "@dotln/kernel";

export const REPAIR_HOST = "repair-host";
export const repairEventTypes = [
  "RepairOpened",
  "RepairTick",
  "RepairCommandPersisted",
  "RepairCommandResult",
  "RepairDerived",
  "RepairCompleted",
  "RepairExhausted",
  "NeedsHuman",
] as const;
export interface RepairOriginal {
  readonly workOrder: WorkOrder;
  readonly authorityEnvelope: AuthorityEnvelope;
  readonly surfaces: readonly string[];
  readonly tests: readonly NamedVerificationTest[];
  readonly criteria: readonly AcceptanceCriterion[];
  readonly roundLimit?: number;
}
/** Scope is admitted separately from verifier output. The registry is host-owned. */
export interface RepairScopeGrant {
  readonly grant: AuthorityGrant;
  readonly surfaces: readonly string[];
  readonly tests: readonly string[];
}
export interface RepairGrants {
  readonly requested: readonly RepairScopeGrant[];
  readonly registry: readonly RepairScopeGrant[];
}
export const noRepairGrants: RepairGrants = { requested: [], registry: [] };
export interface RepairOrder extends RepairOriginal {
  readonly contract: WorktreeVerificationContract;
  readonly contractHash: string;
  readonly round: number;
  readonly executionBaseCommit: string;
  readonly finding: VerificationFinding;
  readonly grantIds: readonly string[];
}
export type RepairDerivation =
  | { readonly kind: "derived"; readonly order: RepairOrder }
  | {
      readonly kind: "NeedsHuman";
      readonly reason: string;
      readonly offending: string;
    };
export const repairContract = (
  order: WorkOrder,
): WorktreeVerificationContract => ({
  workOrderId: order.workOrderId,
  objective: order.objective,
  acceptanceCriteria: [...order.acceptanceCriteria],
  constraints: [...order.constraints],
  nonGoals: [...order.nonGoals],
  requiredEvidence: [...order.requiredEvidence],
});
export const repairHash = (value: unknown): string =>
  `fnv1a64:${fnv1a64(canonicalStringify(value))}`;
export const repairEqual = (a: unknown, b: unknown): boolean =>
  canonicalStringify(a) === canonicalStringify(b);
const unique = (values: readonly string[]) => [...new Set(values)].sort();
export const repairContains = (
  surfaces: readonly string[],
  path: string,
): boolean =>
  surfaces.some(
    (surface) => path === surface || path.startsWith(`${surface}/`),
  );

/** Pure derivation: evidence IDs never become filesystem paths or shell prose. */
export function deriveRepairOrder(
  findingInput: VerificationFinding,
  input: RepairOriginal & {
    readonly subject: VerificationSubject;
    readonly round: number;
  },
  grants: RepairGrants = noRepairGrants,
): RepairDerivation {
  const needs = (offending: string, reason: string): RepairDerivation => ({
    kind: "NeedsHuman",
    offending,
    reason,
  });
  if (!findingInput?.evidenceRefs?.length)
    return needs("evidenceRefs", "finding has no evidence references");
  let finding: VerificationFinding;
  try {
    finding = copyFinding(findingInput);
  } catch {
    return needs("finding", "malformed finding");
  }
  if (finding.severity !== "blocking")
    return needs(
      finding.findingId,
      "automatic repair requires a blocking finding",
    );
  const limit = input.roundLimit ?? 2;
  if (
    !Number.isSafeInteger(limit) ||
    limit < 0 ||
    !Number.isSafeInteger(input.round) ||
    input.round < 0 ||
    input.round >= limit
  )
    return needs("roundLimit", "repair round limit reached or invalid");
  const evidence = finding.evidenceRefs.map((id) =>
    input.subject.evidence.find((e) => e.evidenceId === id),
  );
  for (let i = 0; i < evidence.length; i++) {
    const witness = evidence[i];
    if (
      !witness ||
      witness.criterionId !== finding.criterionId ||
      witness.subjectRevision !== input.subject.revision
    )
      return needs(
        finding.evidenceRefs[i]!,
        "missing or foreign evidence reference",
      );
  }
  const witnesses = evidence.filter(
    (e): e is VerificationEvidence => e !== undefined,
  );
  if (
    !witnesses.some(
      (e) =>
        e.outcome === "fail" &&
        e.observed === finding.observed &&
        e.expected === finding.expected,
    )
  )
    return needs(finding.findingId, "finding lacks its adverse host witness");
  const surfaces = unique([
    ...finding.likelySurface,
    ...witnesses.flatMap((e) => e.codeSurfaces),
  ]);
  const commands: string[] = [];
  for (const step of finding.reproductionSteps) {
    const witness = witnesses.find((e) => e.reproductionSteps.includes(step));
    const command =
      witness?.hostTest?.command ?? witness?.automatedTest ?? step;
    if (witness?.hostTest && witness.automatedTest !== command)
      return needs(step, "host test command differs from evidence");
    commands.push(command);
  }
  const tests = unique(commands);
  const admitted: RepairScopeGrant[] = [];
  for (const requested of grants.requested) {
    const g = requested.grant;
    if (
      !g ||
      !g.grantId ||
      !Number.isSafeInteger(g.version) ||
      g.version < 1 ||
      !["operator", "host-policy", "registered-repository"].includes(
        g.grantedBy,
      ) ||
      !g.reason ||
      g.repo !== input.workOrder.repo ||
      !g.effects.length ||
      g.effects.some(
        (e) =>
          e.includes("*") ||
          !input.authorityEnvelope.allowedEffects.includes(e),
      ) ||
      (g.operations ?? []).some(
        (e) =>
          e.includes("*") || !input.workOrder.allowedOperations.includes(e),
      ) ||
      !grants.registry.some((entry) => repairEqual(entry, requested))
    )
      return needs(
        g?.grantId ?? "grant",
        "scope grant is not admitted by the host registry",
      );
    if (admitted.some((entry) => entry.grant.grantId === g.grantId))
      return needs(g.grantId, "duplicate grant");
    admitted.push(requested);
  }
  const used = new Set<string>();
  for (const path of surfaces) {
    if (!repositoryPath(path)) return needs(path, "invalid repair path");
    if (!repairContains(input.surfaces, path)) {
      const grant = admitted.find(
        (g) =>
          g.surfaces.includes(path) &&
          g.grant.effects.includes("repo.write") &&
          g.grant.operations?.includes("repo.write"),
      );
      if (!grant) return needs(path, "path outside original surfaces");
      used.add(grant.grant.grantId);
    }
  }
  for (const command of tests) {
    if (
      !/^[a-zA-Z0-9_./][a-zA-Z0-9_./-]*(?: [a-zA-Z0-9_./=-]+)*$/u.test(command)
    )
      return needs(command, "reproduction is not an exact named command");
    if (!input.tests.some((test) => test.command === command)) {
      const grant = admitted.find(
        (g) =>
          g.tests.includes(command) &&
          g.grant.effects.includes("shell.run") &&
          g.grant.operations?.includes("shell.run"),
      );
      if (!grant) return needs(command, "command outside original named tests");
      used.add(grant.grant.grantId);
    }
  }
  // Every consumed grant is exactly the expansion, not a wildcard authority source.
  for (const g of admitted.filter((g) => used.has(g.grant.grantId))) {
    if (
      g.surfaces.some(
        (p) => !surfaces.includes(p) || repairContains(input.surfaces, p),
      ) ||
      g.tests.some(
        (c) => !tests.includes(c) || input.tests.some((t) => t.command === c),
      )
    )
      return needs(g.grant.grantId, "grant scope exceeds the exact expansion");
  }
  const contract = repairContract(input.workOrder);
  const round = input.round + 1;
  const order: RepairOrder = {
    workOrder: {
      ...input.workOrder,
      workOrderId: `${input.workOrder.workOrderId}_repair_${round}`,
      knownFacts: [],
      decisions: [],
    },
    authorityEnvelope: input.authorityEnvelope,
    surfaces,
    tests: tests.map(
      (command) =>
        input.tests.find((t) => t.command === command) ?? {
          criterionId: finding.criterionId,
          checkId: `grant:${command}`,
          command,
        },
    ),
    criteria: input.criteria,
    roundLimit: limit,
    contract,
    contractHash: repairHash(contract),
    round,
    executionBaseCommit: input.subject.revision,
    finding,
    grantIds: [...used].sort(),
  };
  // JSON detachment prevents a caller mutating an admitted order after derivation.
  return {
    kind: "derived",
    order: JSON.parse(JSON.stringify(order)) as RepairOrder,
  };
}

export interface RepairState {
  readonly workstreamId: string;
  readonly original: RepairOriginal;
  readonly grants: RepairGrants;
  readonly baseline: VerificationSubject;
  readonly subject: VerificationSubject;
  readonly round: number;
  readonly currentCommit: string;
  readonly continuation: ExecutableProgramV1;
  readonly pending: Command | null;
  readonly emission: EventDraft | null;
  readonly order: RepairOrder | null;
  readonly finding: VerificationFinding | null;
  readonly verified: boolean;
  readonly status: "running" | "complete" | "exhausted" | "needs-human";
  readonly reason: string | null;
}
export function repairEvent(
  state: Pick<RepairState, "workstreamId" | "round" | "finding">,
  type: string,
): EventDraft {
  return {
    schemaVersion: 1,
    type,
    actorId: REPAIR_HOST,
    workstreamId: state.workstreamId,
    occurredAt: 0,
    payload: {
      round: state.round,
      finding: state.finding as unknown as JsonValue,
    },
  };
}
export function repairCommand(
  state: Pick<RepairState, "workstreamId" | "round">,
  kind: "write" | "verify",
): Command {
  return {
    commandId: `cmd_${repairHash([state.workstreamId, state.round, kind]).slice(8)}`,
    workstreamId: state.workstreamId,
    episodeId: `repair_${kind}_${state.round}`,
    intent: {
      kind: "Act",
      effect: kind === "write" ? "repo.write" : "verification.evaluate",
      payload: { round: state.round, kind },
    },
  };
}
export function repairVerificationProgram(
  state: RepairState,
): ExecutableProgramV1 {
  const command = repairCommand(state, "verify");
  const emit = (type: string) =>
    Program.Emit(repairEvent(state, type), Program.Done());
  return Program.Invoke(command.commandId, command.intent, {
    completed: Program.Guard(
      { registryId: "repair.verified", version: 1 },
      emit("RepairCompleted"),
      Program.Guard(
        { registryId: "repair.remaining", version: 1 },
        emit("RepairDerived"),
        emit("RepairExhausted"),
      ),
    ),
  });
}
export function repairRoundProgram(state: RepairState): ExecutableProgramV1 {
  const command = repairCommand(state, "write");
  return Program.Sequence([
    Program.Invoke(command.commandId, command.intent, {
      accepted: Program.Done(),
    }),
    Program.Await(
      { type: "SourceChangeObserved", correlationId: command.commandId },
      { kind: "After", delayMs: 180_000 },
      Program.Done(),
    ),
    repairVerificationProgram(state),
  ]);
}

/** Terminal exhaustion and containment refusals never offer another dispatch. */
export const repairNextAction = (
  state: RepairState,
): "run" | "human" | "none" =>
  state.status === "running"
    ? "run"
    : state.status === "complete"
      ? "none"
      : "human";

import { join, dirname, basename } from "node:path";
import { mkdirSync, existsSync } from "node:fs";
import {
  appendEvent,
  decodeLog,
  replay,
  type Event,
  type EventDraft,
  type JsonValue,
  type Command,
  type Decision,
} from "@dotln/kernel";
import {
  compileVerificationTask,
  type VerificationSubject,
} from "@dotln/compiler";
import {
  initialState,
  projectRuntimeEnvironment,
  seiriReactor,
  sourceChangeAuthorization,
  type RuntimeState,
} from "./reactor.js";
import {
  REPAIR_HOST,
  noRepairGrants,
  repairEqual,
  repairHash,
  repairCommand,
  repairVerificationProgram,
  type RepairOriginal,
  type RepairGrants,
  type RepairState,
} from "./repair.js";
import {
  SourceChangeHost,
  type SourceChangeHostOptions,
} from "./source-change-host.js";
import { WorkerStore } from "./worker-store.js";
import { runFocusedTest } from "./source-change-worktree.js";
import {
  VerificationDriver,
  VerificationHost,
  preflightVerificationRecovery,
} from "./verification-host.js";
import {
  prepareWorktreeVerification,
  assertWorktreeSnapshot,
} from "./verification-worktree.js";
import type { WorkOrderTransport } from "./worker-transport.js";
import type { EvidenceWorkerRequest } from "./verification-protocol.js";

export interface RepairHostOptions {
  readonly store: WorkerStore;
  readonly original: RepairOriginal;
  readonly grants?: RepairGrants;
  readonly baseline: VerificationSubject;
  readonly subject: VerificationSubject;
  readonly snapshotPath: string;
  /** Retained child stores and verification copies, outside target worktrees. */
  readonly directory: string;
  readonly source: Pick<
    SourceChangeHostOptions,
    | "authorityEvidence"
    | "artifactIdentity"
    | "worktreeParent"
    | "launchpadCheckout"
    | "model"
    | "effort"
    | "transport"
  >;
  readonly verifier: {
    readonly transport: WorkOrderTransport<EvidenceWorkerRequest>;
    readonly model: string;
    readonly effort: string;
  };
  readonly now?: () => number;
  readonly onEvent?: (event: Event) => void;
  /** Fault injection after durable child receipt, before parent observation. */
  readonly afterRepairCommit?: () => void;
  readonly afterSnapshotPrepared?: () => void;
}

/** Host effects are selected by the persisted executable program, not a retry loop. */
export class RepairHost {
  private runtime: RuntimeState = initialState();
  private log = "";
  private lastDecision?: Decision<RuntimeState>;
  readonly now: () => number;
  readonly workstreamId: string;
  constructor(readonly options: RepairHostOptions) {
    this.now = options.now ?? Date.now;
    this.workstreamId = `repair_${repairHash(options.original.workOrder.workOrderId).slice(8)}`;
  }
  get state(): RepairState {
    return this.runtime.repair as unknown as RepairState;
  }
  private opening(): Record<string, unknown> {
    const shell = {
      workstreamId: this.workstreamId,
      round: 0,
      finding: null,
    } as RepairState;
    return {
      original: this.options.original,
      grants: this.options.grants ?? noRepairGrants,
      baseline: this.options.baseline,
      subject: this.options.subject,
      continuation: repairVerificationProgram(shell),
      host: {
        directory: this.options.directory,
        snapshotPath: this.options.snapshotPath,
        source: {
          ...this.options.source,
          transport: {
            name: this.options.source.transport.name,
            harnessVersion: this.options.source.transport.harnessVersion,
          },
        },
        verifier: {
          ...this.options.verifier,
          transport: {
            name: this.options.verifier.transport.name,
            harnessVersion: this.options.verifier.transport.harnessVersion,
          },
        },
      },
    };
  }
  private restore = (): void => {
    this.log = this.options.store.read();
    const events = decodeLog(this.log);
    const opening = events.find((e) => e.type === "RepairOpened");
    if (opening && !repairEqual(opening.payload, this.opening()))
      throw new Error("repair recovery request drift");
    if (
      events.some(
        (e) =>
          e.actorId !== REPAIR_HOST || e.workstreamId !== this.workstreamId,
      )
    )
      throw new Error("repair store contains foreign events");
    this.runtime = replay(
      initialState(),
      events,
      seiriReactor,
      {},
      projectRuntimeEnvironment,
    ).state;
  };
  private feed(type: string, payload: unknown, correlationId?: string): Event {
    const draft: EventDraft = {
      schemaVersion: 1,
      type,
      occurredAt: this.now(),
      actorId: REPAIR_HOST,
      workstreamId: this.workstreamId,
      ...(correlationId ? { correlationId } : {}),
      payload: payload as JsonValue,
    };
    const appended = appendEvent(this.log, draft);
    const decision = seiriReactor(this.runtime, appended.event, {
      now: draft.occurredAt,
      rngState: 0,
      predicates: {},
    });
    this.options.store.append(appended.event);
    this.log = appended.log;
    this.runtime = decision.state;
    this.lastDecision = decision;
    this.options.onEvent?.(appended.event);
    return appended.event;
  }
  sourceHost(): SourceChangeHost {
    const order = this.state.order;
    if (!order) throw new Error("repair has no derived order");
    return new SourceChangeHost({
      ...this.options.source,
      store: new WorkerStore(
        join(this.options.directory, `source-${order.round}`),
      ),
      workOrder: order.workOrder,
      authorityEnvelope: order.authorityEnvelope,
      executionBaseCommit: order.executionBaseCommit,
      repairContext: {
        contract: order.contract,
        contractHash: order.contractHash,
        finding: order.finding,
        tests: order.tests,
        grantIds: order.grantIds,
        round: order.round,
      } as unknown as JsonValue,
      branch: `dotln-repair-${repairHash([this.workstreamId, order.round]).slice(8)}`,
      surfaces: order.surfaces,
      testCommand: order.tests[0]!.command,
      commitMessage: `Repair ${order.finding.findingId}\n`,
      now: this.now,
    });
  }
  private async verify(command: Command): Promise<void> {
    const state = this.state;
    const store = new WorkerStore(
      join(this.options.directory, `verification-${state.round}`),
    );
    const stream = `${this.workstreamId}_verify_${state.round}`;
    const saved = decodeLog(store.read()).find(
      (e) => e.type === "RepairSnapshotPrepared",
    );
    let prepared = saved?.payload as unknown as
      { subject: VerificationSubject; snapshotPath: string } | undefined;
    let path =
      state.round === 0
        ? this.options.snapshotPath
        : (prepared?.snapshotPath ?? "");
    if (
      prepared &&
      (dirname(dirname(path)) !== this.options.directory ||
        basename(path) !== "snapshot" ||
        !new RegExp(`^snapshot-${state.round}-[0-9]+$`, "u").test(
          basename(dirname(path)),
        ))
    )
      throw new Error("repair snapshot receipt path drift");
    if (prepared)
      assertWorktreeSnapshot(
        compileVerificationTask(
          "repair_preflight",
          state.original.criteria,
          prepared.subject,
        ),
        path,
      );
    store.acquire(() =>
      preflightVerificationRecovery(
        store,
        stream,
        () => path,
        this.options.verifier.model,
        this.options.verifier.effort,
      ),
    );
    try {
      const driver = new VerificationDriver(store, stream);
      if (driver.state.next === "unopened") {
        if (state.round > 0 && !prepared) {
          // An interrupted, unpublished preparation remains inspectable. A new
          // attempt never edits or adopts its incomplete files.
          let attempt = 0;
          let directory: string;
          do {
            directory = join(
              this.options.directory,
              `snapshot-${state.round}-${attempt++}`,
            );
          } while (existsSync(directory));
          prepared = prepareWorktreeVerification({
            worktree: this.sourceHost().tree.path,
            baseCommit: state.original.workOrder.baseCommit,
            observedCommit: state.currentCommit,
            repo: state.subject.repo,
            contract: this.options.subject.snapshot!.contract,
            criteria: state.original.criteria,
            tests: state.original.tests,
            directory,
          });
          path = prepared.snapshotPath;
          driver.record("RepairSnapshotPrepared", this.now(), {
            subject: prepared.subject,
            snapshotPath: path,
          });
          this.options.afterSnapshotPrepared?.();
        }
        const subject = state.round === 0 ? state.subject : prepared!.subject;
        const capsule = compileVerificationTask(
          "repair_preflight",
          state.original.criteria,
          subject,
        );
        assertWorktreeSnapshot(capsule, path);
        driver.record("VerificationOpened", this.now(), {
          baseline: state.baseline,
          subject,
          criteria: state.original.criteria,
          implementerEpisodeId: `repair_source_${state.round}`,
          episodeNamespace: stream,
          maxRepairs: 0,
          authority: {
            authorityEnvelopeId: "repair.verifier",
            allowedEffects: ["verification.evaluate"],
            deniedEffects: ["repo.write", "repair.propose"],
            resourceLimits: { episodes: 1 },
            requiredEvidence: [],
            expiresAt: state.original.authorityEnvelope.expiresAt,
            revocationEventTypes:
              state.original.authorityEnvelope.revocationEventTypes,
          },
        });
      }
      if (!driver.state.lastResultEventId) {
        driver.persistNext(this.now());
        await new VerificationHost({
          driver,
          transport: this.options.verifier.transport,
          now: this.now,
        }).run(path, this.options.verifier.model, this.options.verifier.effort);
      }
      const events = decodeLog(driver.log);
      const result = events.find(
        (e) => e.eventId === driver.state.lastResultEventId,
      );
      if (!result)
        throw new Error("repair verification has no admitted result");
      const p = result.payload as Record<string, JsonValue>;
      const persisted = events.find((e) => e.type === "CommandPersisted")!;
      const verifierCommand = (
        persisted.payload as unknown as { command: Command }
      ).command;
      const capsule = (
        verifierCommand.intent.payload as Record<string, JsonValue>
      ).capsule;
      this.feed("RepairCommandResult", {
        commandId: command.commandId,
        result: "completed",
        capsule,
        verifierCommand,
        value: p.value,
      });
    } finally {
      store.release();
    }
  }
  async run(): Promise<RepairState> {
    this.options.store.acquire(this.restore);
    try {
      mkdirSync(this.options.directory, { recursive: true });
      if (!this.runtime.repair) this.feed("RepairOpened", this.opening());
      while (this.state.status === "running") {
        if (this.state.emission) {
          this.feed(this.state.emission.type, this.state.emission.payload);
        } else if (this.state.pending) {
          const command = this.state.pending;
          if (command.intent.effect === "repo.write")
            this.feed("RepairCommandResult", {
              commandId: command.commandId,
              result: "accepted",
            });
          else await this.verify(command);
        } else {
          this.feed("RepairTick", {});
          const intent = this.lastDecision!.intents[0];
          if (intent?.kind === "Act") {
            const kind = intent.effect === "repo.write" ? "write" : "verify";
            this.feed("RepairCommandPersisted", {
              command: repairCommand(this.state, kind),
            });
          } else if (!this.state.emission) {
            // A waiting source observation owns an already-persisted child command.
            const source = this.sourceHost();
            const outcome = await source.run();
            if (outcome.status === "refused")
              this.feed("NeedsHuman", {
                reason: "source change refused",
                offending: outcome.refusal.reason,
              });
            else {
              this.options.afterRepairCommit?.();
              const before = source.tree.effect();
              const tests = this.state.order!.tests.map((test) => {
                if (
                  !sourceChangeAuthorization(
                    { kind: "Act", effect: "shell.run", payload: {} },
                    this.state.order!.authorityEnvelope,
                    {
                      now: this.now(),
                      actorId: REPAIR_HOST,
                      workstreamId: this.workstreamId,
                      decisionIndex: this.state.round,
                      intentIndex: 0,
                      evidence: this.options.source.authorityEvidence,
                      revokedBy: decodeLog(source.options.store.read()),
                    },
                  ).authorized
                )
                  throw new Error("repair test authority expired or revoked");
                const result = runFocusedTest(source.tree.path, test.command);
                if (!repairEqual(before, source.tree.effect()))
                  throw new Error(
                    "repair reproduction changed committed source",
                  );
                return result;
              });
              this.feed(
                "SourceChangeObserved",
                { observation: outcome.observation, tests },
                repairCommand(this.state, "write").commandId,
              );
            }
          }
        }
      }
      return this.state;
    } finally {
      this.options.store.release();
    }
  }
}

import {
  canonicalStringify,
  compileLoadout,
  requireCompiled,
  type CompilationEnvironment,
  type CompiledPresencePolicy,
  type LoadoutGraph,
} from "@dotln/compiler";
import {
  authorize,
  commandId,
  type Event,
  type PredicateRegistry,
} from "@dotln/kernel";
import {
  assertActorResult,
  scriptResultVerified,
  assertActorSpec,
  type ActorSpec,
} from "./actor-contract.js";
import {
  PresenceMachine,
  presencePredicates,
  type PresenceSnapshot,
} from "./presence-machine.js";
import {
  decodePresenceObservation,
  presenceActorKey,
} from "./presence-signals.js";
import { assertHandoffPacket, type HandoffPacket } from "./handoff-contract.js";
import { isWriterRequest } from "./worker-protocol.js";

export interface ResidentConfiguration {
  graph: LoadoutGraph;
  environment: CompilationEnvironment;
  policyId: string;
  actors: Record<string, ActorSpec>;
  evidence: string[];
  heartbeatBudgetMs?: number;
}
export interface ResidentState {
  configuration: ResidentConfiguration | null;
  policy: CompiledPresencePolicy | null;
  machine: PresenceSnapshot | null;
  at: number;
  present: boolean;
  episodes: Record<string, "dispatched" | "observed" | "lost">;
  episodePhases: Record<string, string>;
  episodeGenerations: Record<string, number>;
  revokedBy: Event[];
  lastNoOp: string | null;
  lastHumanAt: number | null;
  actors: Record<
    string,
    {
      lastHeartbeatAt: number;
      status: "live" | "stalled" | "stopped";
      failureAt?: number;
      episodeId?: string;
    }
  >;
  progress: Record<string, number>;
  handoffs: Record<
    string,
    {
      packet: HandoffPacket;
      phaseId: string;
      generation: number;
      answer?: string;
    }
  >;
}
export function decodeResidentConfiguration(
  value: unknown,
): ResidentConfiguration {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid resident configuration");
  const v = value as ResidentConfiguration;
  if (
    Object.keys(v).some(
      (key) =>
        ![
          "graph",
          "environment",
          "policyId",
          "actors",
          "evidence",
          "heartbeatBudgetMs",
        ].includes(key),
    ) ||
    typeof v.policyId !== "string" ||
    !v.actors ||
    typeof v.actors !== "object" ||
    Array.isArray(v.actors) ||
    !Array.isArray(v.evidence) ||
    v.evidence.some((item) => typeof item !== "string")
  )
    throw new Error("invalid resident configuration fields");
  if (
    v.heartbeatBudgetMs !== undefined &&
    (!Number.isSafeInteger(v.heartbeatBudgetMs) || v.heartbeatBudgetMs < 1)
  )
    throw new Error("invalid resident heartbeat budget");
  const program = requireCompiled(compileLoadout(v.graph, v.environment));
  const policy = program.presence?.find((p) => p.policyId === v.policyId);
  if (!policy) throw new Error("resident policy is not compiled");
  if (Object.keys(v.actors).length !== policy.phases.length)
    throw new Error("resident requires one actor per phase");
  for (const phase of policy.phases) {
    if (!Object.hasOwn(v.actors, phase.phaseId))
      throw new Error("resident phase actor is missing");
    assertActorSpec(v.actors[phase.phaseId]);
  }
  return structuredClone(v);
}
export const emptyResidentState = (): ResidentState => ({
  configuration: null,
  policy: null,
  machine: null,
  at: 0,
  present: true,
  episodes: {},
  episodePhases: {},
  episodeGenerations: {},
  revokedBy: [],
  lastNoOp: null,
  lastHumanAt: null,
  actors: {},
  progress: {},
  handoffs: {},
});
export function residentMachine(
  state: ResidentState,
  predicates: PredicateRegistry = {},
) {
  if (!state.policy || !state.machine)
    throw new Error("resident is not configured");
  return new PresenceMachine(
    state.policy,
    { ...predicates, ...presencePredicates },
    state.machine,
  );
}
export function residentEpisodeId(
  machine: PresenceMachine,
  dueAt: number,
): string {
  return commandId(
    "resident",
    canonicalStringify([
      machine.compiled.policyId,
      machine.state,
      machine.phase()!.cadence,
      dueAt,
      machine.generation,
    ]),
    0,
    0,
  ).replace("cmd_", "script_");
}
export const residentEventTypes = [
  "ResidentConfigured",
  "ClockSampled",
  "ScriptEpisodeDispatched",
  "ScriptEpisodeObserved",
  "ScriptEpisodeLost",
  "ScriptEpisodeRefused",
  "ActorUnavailable",
  "OperatorPresenceObserved",
  "HandoffRequested",
  "HandoffAnswered",
  "CliWorkerObserved",
] as const;

function expireActorHeartbeats(state: ResidentState) {
  const budget = state.configuration?.heartbeatBudgetMs ?? 30000;
  for (const actor of Object.values(state.actors)) {
    if (actor.status === "live" && state.at - actor.lastHeartbeatAt >= budget) {
      actor.status = "stalled";
      actor.failureAt = actor.lastHeartbeatAt + budget;
    }
  }
}

export function residentRefusal(
  state: ResidentState,
  machine: PresenceMachine,
): string | null {
  const phase = machine.phase()!;
  const spec = state.configuration!.actors[phase.phaseId]!;
  const orderId =
    spec.worker?.request.workOrder.workOrderId ?? spec.handoff?.workOrderId;
  if (
    orderId &&
    Object.values(state.handoffs).some(
      (h) => h.packet.workOrderId === orderId && h.answer === undefined,
    )
  )
    return "work order is waiting for a human handoff answer";
  if (!phase.scope.surfaces.includes(spec.surface))
    return "actor surface is outside phase scope";
  const limits: Record<string, number> = { ...phase.scope.budget };
  for (const [resource, amount] of Object.entries(phase.scope.changeSize))
    limits[resource] = Math.min(limits[resource] ?? Infinity, amount);
  if (
    Object.keys(limits).some((key) => !Object.hasOwn(spec.resources, key)) ||
    Object.entries(spec.resources).some(
      ([resource, amount]) =>
        amount > (limits[resource] ?? 0) ||
        amount >
          (Object.hasOwn(phase.effectiveEnvelope.resourceLimits, resource)
            ? phase.effectiveEnvelope.resourceLimits[resource]!
            : 0),
    )
  )
    return "actor resource reservation exceeds phase scope or authority budget";
  const authorization = authorize(
    { kind: "Act", effect: spec.effect, payload: {} },
    phase.effectiveEnvelope,
    {
      now: state.at,
      actorId: spec.kind,
      workstreamId: "resident",
      decisionIndex: 0,
      intentIndex: 0,
      evidence: state.configuration!.evidence,
      revokedBy: state.revokedBy,
      state: machine.projected(),
      predicateEnv: { rngState: 0, predicates: machine.predicates },
    },
  );
  if (spec.worker) {
    const request = spec.worker.request;
    const envelope = phase.effectiveEnvelope;
    const effects = [...request.workOrder.allowedOperations];
    if (isWriterRequest(request)) {
      const authority = request.authorityEnvelope;
      if (
        authority.expiresAt > envelope.expiresAt ||
        Object.entries(authority.resourceLimits).some(
          ([key, amount]) => amount > (spec.resources[key] ?? 0),
        ) ||
        envelope.requiredEvidence.some(
          (e) => !authority.requiredEvidence.includes(e),
        ) ||
        envelope.revocationEventTypes.some(
          (e) => !authority.revocationEventTypes.includes(e),
        ) ||
        authority.revocationEventTypes.some(
          (e) => !envelope.revocationEventTypes.includes(e),
        ) ||
        (authority.revocationConditions?.length ?? 0) > 0 ||
        (envelope.revocationConditions?.length ?? 0) > 0
      )
        return "worker authority exceeds or cannot represent the resident phase";
      effects.push(
        ...authority.allowedEffects.filter((e) => !effects.includes(e)),
      );
    }
    for (const effect of effects) {
      for (const candidate of isWriterRequest(request)
        ? [envelope, request.authorityEnvelope]
        : [envelope]) {
        const check = authorize(
          { kind: "Act", effect, payload: {} },
          candidate,
          {
            now: state.at,
            actorId: spec.kind,
            workstreamId: "resident",
            decisionIndex: 0,
            intentIndex: 0,
            evidence: state.configuration!.evidence,
            revokedBy: state.revokedBy,
            state: machine.projected(),
            predicateEnv: { rngState: 0, predicates: machine.predicates },
          },
        );
        if (!check.authorized)
          return "worker operations exceed the resident phase authority";
      }
    }
  }
  return authorization.authorized ? null : authorization.refusal.payload.reason;
}

export function foldResidentEvent(
  previous: ResidentState | undefined,
  event: Event,
  predicates: PredicateRegistry,
): ResidentState {
  const state = structuredClone({ ...emptyResidentState(), ...previous });
  const payload = event.payload as Record<string, unknown>;
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    throw new Error("invalid resident event payload");
  if (event.type === "ResidentConfigured") {
    const configuration = decodeResidentConfiguration(payload["configuration"]);
    if (state.configuration) {
      if (
        canonicalStringify(configuration) !==
        canonicalStringify(state.configuration)
      )
        throw new Error("resident configuration changed within a store");
      return state;
    }
    state.configuration = configuration;
    state.policy = requireCompiled(
      compileLoadout(configuration.graph, configuration.environment),
    ).presence!.find((p) => p.policyId === configuration.policyId)!;
    const machine = new PresenceMachine(state.policy);
    if (!state.present) machine.absence(state.at);
    state.machine = machine.snapshot();
    return state;
  }
  if (event.type === "ClockSampled") {
    const at = payload["at"];
    if (
      typeof at !== "number" ||
      !Number.isFinite(at) ||
      at < 0 ||
      at !== event.occurredAt
    )
      throw new Error("invalid recorded clock sample");
    state.at = Math.max(state.at, at); // A backwards wall clock cannot replenish a phase.
    expireActorHeartbeats(state);
  }
  let humanChanged = false;
  if (event.type === "OperatorPresenceObserved") {
    const observation = decodePresenceObservation(payload);
    if (observation.at !== event.occurredAt)
      throw new Error("presence time differs from event");
    state.at = Math.max(state.at, observation.at);
    // A late heartbeat cannot hide a deadline crossed before its arrival.
    expireActorHeartbeats(state);
    const { signal, origin, stamp } = observation;
    if (
      origin === "human" &&
      observation.at >= state.at &&
      observation.at >= (state.lastHumanAt ?? 0)
    ) {
      state.lastHumanAt = observation.at;
      state.present = signal.kind !== "away";
      humanChanged = true;
    }
    if (origin === "actor" && signal.kind === "heartbeat") {
      const key = presenceActorKey(signal, stamp);
      const old = state.actors[key];
      // A late heartbeat cannot resurrect a completed/lost resident episode.
      if (
        observation.at >= state.at &&
        (!stamp ||
          !["observed", "lost"].includes(
            state.episodes[stamp.episodeId] ?? "",
          )) &&
        (!old || observation.at >= old.lastHeartbeatAt)
      ) {
        state.actors[key] = {
          lastHeartbeatAt: observation.at,
          status: "live",
          ...(stamp ? { episodeId: stamp.episodeId } : {}),
          ...(old?.failureAt === undefined ? {} : { failureAt: old.failureAt }),
        };
      }
    }
    if (origin === "task" && signal.kind === "progress")
      state.progress = {
        ...state.progress,
        [signal.taskId]: Math.max(
          Object.hasOwn(state.progress, signal.taskId)
            ? state.progress[signal.taskId]!
            : 0,
          observation.at,
        ),
      };
  }
  if (event.type === "OperatorPresenceChanged") {
    if (
      typeof payload["presence"] !== "string" ||
      !["away", "returned"].includes(payload["presence"])
    )
      throw new Error("invalid resident presence");
    state.present = payload["presence"] === "returned";
    state.lastHumanAt = state.at;
    humanChanged = true;
  }
  if (
    event.type === "ClockSampled" &&
    state.present &&
    state.lastHumanAt !== null &&
    state.policy?.humanIdleMs !== undefined &&
    state.at - state.lastHumanAt >= state.policy.humanIdleMs
  ) {
    state.present = false;
    humanChanged = true;
  }
  if (!state.machine) {
    if (
      ![
        "ClockSampled",
        "OperatorPresenceChanged",
        "OperatorPresenceObserved",
      ].includes(event.type)
    )
      throw new Error("resident event precedes configuration");
    return state;
  }
  const machine = residentMachine(state, predicates);
  machine.now = state.at;
  if (humanChanged) {
    if (state.present) machine.returned();
    else machine.absence();
  }
  if (event.type === "ClockSampled") machine.transition("idle-expired");
  if (
    state.policy!.phases.some(
      (phase) =>
        phase.effectiveEnvelope.revocationEventTypes.includes(event.type) ||
        phase.effectiveEnvelope.revocationConditions?.length,
    )
  )
    state.revokedBy.push(event);
  if (event.type === "ScriptEpisodeDispatched") {
    const dueAt = machine.due(state.at);
    const id = payload["episodeId"];
    const phase = machine.phase();
    const spec = phase ? state.configuration!.actors[phase.phaseId]! : null;
    if (
      typeof id !== "string" ||
      dueAt === null ||
      id !== residentEpisodeId(machine, dueAt) ||
      Object.hasOwn(state.episodes, id) ||
      payload["dueAt"] !== dueAt ||
      payload["phaseId"] !== phase!.phaseId ||
      payload["kind"] !== spec!.kind ||
      payload["effect"] !== spec!.effect ||
      payload["authorityEnvelopeId"] !==
        phase!.effectiveEnvelope.authorityEnvelopeId ||
      residentRefusal(state, machine)
    )
      throw new Error("invalid or repeated resident dispatch");
    state.episodes[id] = "dispatched";
    state.episodePhases[id] = phase!.phaseId;
    state.episodeGenerations[id] = machine.generation;
    state.actors[`episode:${id}`] = {
      lastHeartbeatAt: state.at,
      status: "live",
      episodeId: id,
    };
    machine.dispatch(id);
    state.lastNoOp = null;
  }
  if (event.type === "HandoffRequested") {
    const packet = payload["packet"];
    assertHandoffPacket(packet);
    const id = packet.episodeId;
    const phaseId = state.episodePhases[id];
    const spec = phaseId ? state.configuration!.actors[phaseId] : undefined;
    if (
      state.episodes[id] !== "dispatched" ||
      !spec?.handoff ||
      canonicalStringify(packet) !==
        canonicalStringify({ ...spec.handoff, episodeId: id }) ||
      Object.values(state.handoffs).some(
        (h) =>
          h.packet.workOrderId === packet.workOrderId && h.answer === undefined,
      )
    )
      throw new Error("invalid or repeated handoff request");
    state.handoffs[id] = {
      packet,
      phaseId: phaseId!,
      generation: state.episodeGenerations[id]!,
    };
    state.episodes[id] = "observed";
    state.actors[`episode:${id}`]!.status = "stopped";
    // Waiting is durable state, not a live actor or an occupied process slot.
    machine.waitForInput(id);
  }
  if (event.type === "HandoffAnswered") {
    const id = payload["episodeId"];
    const handoff = typeof id === "string" ? state.handoffs[id] : undefined;
    const option = payload["optionId"];
    if (
      event.actorId !== "operator" ||
      payload["origin"] !== "human" ||
      !handoff ||
      handoff.answer !== undefined ||
      payload["workOrderId"] !== handoff.packet.workOrderId ||
      typeof option !== "string" ||
      !handoff.packet.options.some((o) => o.id === option)
    )
      throw new Error("invalid, stale or repeated human handoff answer");
    handoff.answer = option;
    state.at = Math.max(state.at, event.occurredAt);
    machine.now = state.at;
    machine.transition("idle-expired");
    if (
      !machine.present &&
      !machine.current &&
      machine.state === handoff.phaseId &&
      machine.generation === handoff.generation
    ) {
      machine.dispatch(handoff.packet.episodeId);
      machine.outcome("verified-success", handoff.packet.episodeId);
    }
    state.lastNoOp = null;
  }
  if (
    [
      "ScriptEpisodeObserved",
      "CliWorkerObserved",
      "ScriptEpisodeLost",
    ].includes(event.type)
  ) {
    const id = payload["episodeId"];
    if (typeof id !== "string" || state.episodes[id] !== "dispatched")
      throw new Error("resident outcome has no pending dispatch");
    const lost = event.type === "ScriptEpisodeLost";
    if (lost && (typeof payload["reason"] !== "string" || !payload["reason"]))
      throw new Error("lost episode needs a reason");
    if (!lost) {
      assertActorResult(payload);
      const spec = state.configuration!.actors[state.episodePhases[id]!]!;
      if ((event.type === "CliWorkerObserved") !== (spec.kind === "cli-worker"))
        throw new Error("actor observation kind differs from dispatch");
      const verified = scriptResultVerified(spec, payload, id);
      if (payload.verified !== verified)
        throw new Error("script verification contradicts recorded output");
    }
    state.episodes[id] = lost ? "lost" : "observed";
    const actor = state.actors[`episode:${id}`];
    if (actor) actor.status = "stopped";
    machine.outcome(
      !lost && payload["verified"] === true ? "verified-success" : "failure",
      id,
    );
  }
  if (["ActorUnavailable", "ScriptEpisodeRefused"].includes(event.type)) {
    if (
      typeof payload["reason"] !== "string" ||
      !payload["reason"] ||
      !state.policy!.phases.some((p) => p.phaseId === payload["phaseId"])
    )
      throw new Error("resident NoOp needs a reason and phase");
    state.lastNoOp = payload["reason"];
  }
  state.machine = machine.snapshot();
  return state;
}

/** Replayable observations. No process, launch-path or ambient-clock input. */
export const PRESENCE_HOOK_EVENTS = [
  "UserPromptSubmit",
  "PreToolUse",
  "PostToolUse",
  "Stop",
] as const;
export type PresenceHookEvent = (typeof PRESENCE_HOOK_EVENTS)[number];
export type PresenceSignal =
  | { kind: "away" }
  | { kind: "back" }
  | {
      kind: "heartbeat";
      event: PresenceHookEvent;
      sessionId: string;
      interaction?: "human" | "scripted" | "unknown";
    }
  | { kind: "progress"; taskId: string };
export interface ResidentStamp {
  episodeId: string;
}
export interface OperatorPresenceObserved {
  signal: PresenceSignal;
  origin: "human" | "actor" | "task";
  at: number;
  stamp?: ResidentStamp;
}

export function classifyPresenceSignal(
  signal: PresenceSignal,
  stamp?: ResidentStamp,
): OperatorPresenceObserved["origin"] {
  if (signal.kind === "progress") return "task";
  if (signal.kind === "away" || signal.kind === "back") return "human";
  return !stamp &&
    signal.event === "UserPromptSubmit" &&
    signal.interaction === "human"
    ? "human"
    : "actor";
}
const identity = (value: unknown): value is string =>
  typeof value === "string" &&
  value.length > 0 &&
  value.length <= 256 &&
  !/[\u0000-\u0020\u007f]/u.test(value);
export function decodePresenceObservation(
  value: unknown,
): OperatorPresenceObserved {
  const fail = (): never => {
    throw new Error("invalid presence observation");
  };
  if (!value || typeof value !== "object" || Array.isArray(value))
    return fail();
  const v = value as OperatorPresenceObserved;
  if (
    Object.keys(v).some(
      (k) => !["signal", "origin", "at", "stamp"].includes(k),
    ) ||
    !Number.isFinite(v.at) ||
    v.at < 0 ||
    !v.signal ||
    typeof v.signal !== "object" ||
    Array.isArray(v.signal)
  )
    return fail();
  if (
    v.stamp !== undefined &&
    (!v.stamp ||
      typeof v.stamp !== "object" ||
      Array.isArray(v.stamp) ||
      Object.keys(v.stamp).some((k) => k !== "episodeId") ||
      !identity(v.stamp.episodeId))
  )
    return fail();
  const s = v.signal;
  let keys: string[];
  switch (s.kind) {
    case "away":
    case "back":
      keys = ["kind"];
      if (v.stamp) return fail();
      break;
    case "heartbeat":
      keys = ["kind", "event", "sessionId", "interaction"];
      if (
        !PRESENCE_HOOK_EVENTS.includes(s.event) ||
        !identity(s.sessionId) ||
        (s.interaction !== undefined &&
          !["human", "scripted", "unknown"].includes(s.interaction))
      )
        return fail();
      break;
    case "progress":
      keys = ["kind", "taskId"];
      if (!identity(s.taskId) || v.stamp) return fail();
      break;
    default:
      return fail();
  }
  if (
    Object.keys(s).some((k) => !keys.includes(k)) ||
    v.origin !== classifyPresenceSignal(s, v.stamp)
  )
    return fail();
  return structuredClone(v);
}
export const presenceActorKey = (
  signal: Extract<PresenceSignal, { kind: "heartbeat" }>,
  stamp?: ResidentStamp,
) => (stamp ? `episode:${stamp.episodeId}` : `session:${signal.sessionId}`);

import type {
  CompiledPresencePolicy,
  PresenceTransition,
} from "@dotln/compiler";
import {
  evaluateCadence,
  type JsonValue,
  type PredicateRegistry,
} from "@dotln/kernel";

const field = (state: JsonValue, key: string) =>
  (state as Record<string, JsonValue>)[key];
export const presencePredicates: PredicateRegistry = {
  "dotln.presence.phase-ready": {
    1: ({ state }, params) =>
      field(state, "present") === false &&
      field(state, "phase") === params["phaseId"] &&
      field(state, "policyId") === params["policyId"] &&
      field(state, "inFlight") === false,
  },
  "dotln.presence.returned": {
    1: ({ state }) => field(state, "present") === true,
  },
  "dotln.presence.interrupt-phase": {
    1: ({ state }, params) =>
      field(state, "present") === true &&
      params["discretionary"] === true &&
      params["inFlightOnReturn"] === "kill",
  },
};
export interface PresenceSnapshot {
  state: string;
  present: boolean;
  now: number;
  armedAt: number;
  lastActivity: number;
  generation: number;
  current: {
    id: string;
    generation: number;
    discretionary: boolean;
    status: string;
  } | null;
}

/** The WO-067 table interpreter. All time and outcomes are explicit inputs. */
export class PresenceMachine {
  state: string;
  present = true;
  now = 0;
  armedAt = 0;
  lastActivity = 0;
  generation = 0;
  current: PresenceSnapshot["current"] = null;
  readonly transcript: string[] = [];
  constructor(
    readonly compiled: CompiledPresencePolicy,
    readonly predicates: PredicateRegistry = presencePredicates,
    snapshot?: PresenceSnapshot,
  ) {
    this.state = compiled.statechart.initial;
    if (snapshot) Object.assign(this, structuredClone(snapshot));
  }
  snapshot(): PresenceSnapshot {
    const { state, present, now, armedAt, lastActivity, generation, current } =
      this;
    return { state, present, now, armedAt, lastActivity, generation, current };
  }
  phase() {
    return this.compiled.phases.find((phase) => phase.phaseId === this.state);
  }
  projected() {
    return {
      present: this.present,
      phase: this.state,
      policyId: this.compiled.policyId,
      inFlight: this.current !== null,
    };
  }
  transition(on: PresenceTransition["on"], episode?: string) {
    const transition = this.compiled.statechart.transitions.find(
      (t) => t.from === this.state && t.on === on,
    );
    if (!transition) return;
    if (
      transition.guard === "current-policy-episode-while-absent" &&
      (this.present ||
        !this.current ||
        episode !== this.current.id ||
        this.current.generation !== this.generation)
    )
      return;
    if (transition.guard === "idle-deadline-while-absent") {
      const deadline = evaluateCadence(
        this.compiled.idleCadence,
        this.projected(),
        { now: this.lastActivity, rngState: 0, predicates: this.predicates },
      );
      if (
        this.present ||
        this.current ||
        deadline.dueAt === null ||
        this.now < deadline.dueAt
      )
        return;
    }
    this.state = transition.to;
    for (const action of transition.actions) {
      switch (action) {
        case "arm-phase":
          this.armedAt = this.now;
          this.lastActivity = this.now;
          break;
        case "cancel-pending":
        case "reset-progress":
          this.generation += 1;
          break;
        case "expire-phase":
          this.transcript.push("expired:attention,work-scope,effect-authority");
          break;
        case "finish-discretionary":
          if (this.current?.discretionary) {
            this.current.status = "finishing";
            this.transcript.push("in-flight:finish");
          }
          break;
        case "kill-discretionary":
          if (this.current?.discretionary) {
            this.current = null;
            this.transcript.push("in-flight:kill");
          }
          break;
        case "preserve-foreground":
          break; // Foreground state is owned by its own slice.
      }
    }
    this.transcript.push(`${on}:${this.state}`);
  }
  absence(at = this.now) {
    this.now = at;
    if (!this.present) return;
    this.present = false;
    this.transition("absence");
  }
  returned(at = this.now) {
    this.now = at;
    this.present = true;
    this.transition("return");
  }
  outcome(
    kind: "verified-success" | "failure" | "unverified",
    episode: string,
    at = this.now,
  ) {
    this.now = at;
    if (kind !== "unverified") this.transition(kind, episode);
    if (kind !== "unverified" && this.current?.id === episode) {
      this.current = null;
      this.lastActivity = at;
    }
  }
  /** A durable human question frees the process slot without failing/resetting
   * the policy. Its recorded generation binds the later answer continuation. */
  waitForInput(episode: string) {
    if (this.current?.id === episode) this.current = null;
  }
  due(at: number): number | null {
    this.now = at;
    this.transition("idle-expired");
    const phase = this.phase();
    if (!phase) {
      this.transcript.push(`NoOp:${this.state}`);
      return null;
    }
    const evaluation = evaluateCadence(phase.cadence, this.projected(), {
      now: this.armedAt,
      rngState: 0,
      predicates: this.predicates,
    });
    if (evaluation.dueAt === null || at < evaluation.dueAt) {
      this.transcript.push("NoOp:gate-or-cadence");
      return null;
    }
    if (phase.availability.kind === "NoOp") {
      this.transcript.push(`NoOp:${phase.availability.reason}`);
      return null;
    }
    return evaluation.dueAt;
  }
  dispatch(id: string) {
    const phase = this.phase();
    if (!phase || this.present || this.current)
      throw new Error("presence dispatch is not ready");
    this.current = {
      id,
      generation: this.generation,
      discretionary: phase.discretionary,
      status: "running",
    };
    this.lastActivity = this.now;
    this.transcript.push(`dispatch:${phase.phaseId}`);
  }
}

import { fork, spawnSync } from "node:child_process";
