} from "./actor-contract.js";
export * from "./actor-contract.js";

export function scriptAvailability(): string | null {
  if (process.platform !== "darwin")
    return "script offline boundary unavailable: this adapter requires macOS sandbox-exec";
  const probe = spawnSync(
    "/usr/bin/sandbox-exec",
    ["-p", SCRIPT_SANDBOX, "/usr/bin/true"],
    { env: {}, encoding: "utf8", timeout: 2000 },
  );
  return probe.status === 0
    ? null
    : "script offline boundary unavailable: sandbox-exec refused its local probe";
}
function runScript(
  spec: ActorSpec,
  context?: { residentStore: string; episodeId: string },
): ActorRun {
  assertActorSpec(spec);
  const child = fork(
    fileURLToPath(new URL("./script-episode.js", import.meta.url)),
    [],
    {
      env: {},
      execArgv: [],
      cwd: spec.cwd,
      stdio: ["ignore", "ignore", "ignore", "ipc"],
    },
  );
  let observed: ActorResult | undefined;
  const completed = new Promise<ActorResult>((resolve) => {
    child.on("message", (result) => {
      observed = result as ActorResult;
    });
    child.on("error", () => {});
    child.on("close", () =>
      resolve(
        observed ?? {
          exitCode: null,
          signal: null,
          stdoutSha256:
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
          firstLine: "",
          verified: false,
          reason: "script supervisor exited without an observation",
        },
      ),
    );
  });
  child.send({ spec, profile: SCRIPT_SANDBOX, context });
  return {
    completed,
    kill: () => {
      if (child.connected) child.send({ kill: true });
    },
  };
}
const unavailable = (kind: ActorKind, reason: string): ActorAdapter => ({
  kind,
  available: () => reason,
  run: () => {
    throw new Error(reason);
  },
});
export const actorCatalog: Readonly<Record<ActorKind, ActorAdapter>> = {
  script: { kind: "script", available: scriptAvailability, run: runScript },
  "cli-worker": cliWorkerAdapter(),
  "human-handoff": humanHandoffAdapter,
  "local-model": unavailable(
    "local-model",
    "local-model is unavailable until WO-110",
  ),
};

import {
  decodeDiscoveryReport,
  discoveryOutputSha256,
  type DiscoveryReport,
} from "./work-candidate.js";
import {
  assertCliActorSpec,
  assertCliObservation,
  type CliActorSpec,
  type CliActorObservation,
} from "./cli-actor-contract.js";
import {
  assertHandoffQuestion,
  type HandoffQuestion,
  type HandoffPacket,
} from "./handoff-contract.js";
/** Pure actor declarations and persisted-result validation; no process access. */
export const ACTOR_KINDS = [
  "script",
  "cli-worker",
  "human-handoff",
  "local-model",
] as const;
export type ActorKind = (typeof ACTOR_KINDS)[number];
export type ActorSpec = {
  kind: ActorKind;
  effect: string;
  surface: string;
  resources: Record<string, number>;
  command?: readonly string[];
  cwd?: string;
  timeoutMs?: number;
  expectedStdoutSha256?: string;
  outputContract?: "work-candidates-v1";
  worker?: CliActorSpec;
  handoff?: HandoffQuestion;
};
export interface ActorResult {
  worker?: CliActorObservation;
  discovery?: DiscoveryReport;
  exitCode: number | null;
  signal: string | null;
  stdoutSha256: string;
  firstLine: string;
  verified: boolean;
  reason: string;
}
export interface ActorRun {
  handoff?: HandoffPacket;
  completed: Promise<ActorResult>;
  kill(): void;
}
export function assertActorResult(
  value: unknown,
): asserts value is ActorResult {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid script observation");
  const v = value as ActorResult;
  if (v.discovery !== undefined) decodeDiscoveryReport(v.discovery);
  if (
    (v.exitCode !== null &&
      (!Number.isSafeInteger(v.exitCode) || v.exitCode < 0)) ||
    (v.signal !== null && typeof v.signal !== "string") ||
    typeof v.stdoutSha256 !== "string" ||
    !/^[a-f0-9]{64}$/u.test(v.stdoutSha256) ||
    typeof v.firstLine !== "string" ||
    v.firstLine.length > 160 ||
    /[\r\n]/u.test(v.firstLine) ||
    typeof v.verified !== "boolean" ||
    typeof v.reason !== "string" ||
    !v.reason
  )
    throw new Error("invalid script observation fields");
}
export interface ActorAdapter {
  kind: ActorKind;
  available(spec?: ActorSpec): string | null;
  run(
    spec: ActorSpec,
    context?: { residentStore: string; episodeId: string },
  ): ActorRun;
}
export const SCRIPT_SANDBOX = "(version 1)(allow default)(deny network*)";
export function assertActorSpec(value: unknown): asserts value is ActorSpec {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid resident actor");
  const v = value as Record<string, unknown>;
  if (
    Object.keys(v).some(
      (key) =>
        ![
          "kind",
          "effect",
          "surface",
          "resources",
          "command",
          "cwd",
          "timeoutMs",
          "expectedStdoutSha256",
          "outputContract",
          "worker",
          "handoff",
        ].includes(key),
    ) ||
    !ACTOR_KINDS.includes(v.kind as ActorKind) ||
    typeof v.effect !== "string" ||
    !v.effect ||
    typeof v.surface !== "string" ||
    !v.surface ||
    !v.resources ||
    typeof v.resources !== "object" ||
    Array.isArray(v.resources) ||
    Object.values(v.resources).some(
      (amount) => !Number.isSafeInteger(amount) || Number(amount) < 0,
    )
  )
    throw new Error("invalid resident actor declaration");
  if (v.kind === "cli-worker") {
    assertCliActorSpec(v.worker);
    if (
      v.worker.request.command.intent.kind !== "Act" ||
      v.worker.request.command.intent.effect !== v.effect
    )
      throw new Error("CLI actor effect differs from request");
  } else if (v.worker !== undefined)
    throw new Error("worker request on another actor kind");
  if (v.kind === "human-handoff") assertHandoffQuestion(v.handoff);
  else if (v.handoff !== undefined)
    throw new Error("handoff question on another actor kind");
  if (
    v.kind === "script" &&
    (!Array.isArray(v.command) ||
      !v.command.length ||
      v.command.length > 256 ||
      v.command.some(
        (part) =>
          typeof part !== "string" ||
          part.length > 16384 ||
          part.includes("\0"),
      ) ||
      !v.command[0].startsWith("/") ||
      typeof v.cwd !== "string" ||
      !v.cwd.startsWith("/") ||
      v.cwd.includes("\0") ||
      !Number.isSafeInteger(v.timeoutMs) ||
      Number(v.timeoutMs) <= 0 ||
      Number(v.timeoutMs) > 180000 ||
      !(v.outputContract === "work-candidates-v1"
        ? v.expectedStdoutSha256 === undefined
        : v.outputContract === undefined &&
          typeof v.expectedStdoutSha256 === "string" &&
          /^[a-f0-9]{64}$/u.test(v.expectedStdoutSha256)))
  )
    throw new Error(
      "script requires absolute command/cwd, bounded timeout and exactly one output contract",
    );
}

/** Schema verification is an observation contract, never repair verification. */
export function scriptResultVerified(
  spec: ActorSpec,
  result: ActorResult,
  episodeId?: string,
): boolean {
  if (spec.kind === "cli-worker") {
    assertCliObservation(
      result.worker,
      spec.worker!,
      episodeId ?? result.worker?.launch.episodeId ?? "",
    );
    return false; // A harness completion claim is not independent verification.
  }
  if (result.worker !== undefined)
    throw new Error("CLI result on another actor kind");
  if (spec.kind !== "script") return false;
  if (spec.outputContract === "work-candidates-v1") {
    if (result.discovery === undefined) return false;
    decodeDiscoveryReport(result.discovery);
    if (result.stdoutSha256 !== discoveryOutputSha256(result.discovery))
      throw new Error("discovery digest differs from structured output");
    if (result.firstLine !== JSON.stringify(result.discovery).slice(0, 160))
      throw new Error("discovery first line differs from structured output");
  } else if (result.discovery !== undefined) {
    throw new Error("discovery result on a digest-only actor");
  }
  return (
    result.exitCode === 0 &&
    result.signal === null &&
    result.reason === "completed" &&
    (spec.outputContract === "work-candidates-v1" ||
      result.stdoutSha256 === spec.expectedStdoutSha256)
  );
}

import {
  isWriterRequest,
  validateRequest,
  validateWriterRequest,
  parseWorkerResult,
  parseStoredWriterResult,
  type WorkerRequest,
  type WriterRequest,
  type WorkerResult,
  type WriterResult,
} from "./worker-protocol.js";

export type CliTransport = "claude-cli-print" | "codex-cli-exec";
export interface CliActorSpec {
  transport: CliTransport;
  request: WorkerRequest | WriterRequest;
}
export const DETACHED_LAUNCH_ROWS = {
  "claude-cli-print": {
    row: "C-U1",
    label: "observed",
    reason: "detached parent, stored CLI authentication; lifetime unknown",
  },
  "codex-cli-exec": {
    row: "X-U1",
    label: "observed",
    reason: "detached parent, stored CLI authentication; lifetime unknown",
  },
} as const;
export interface CliLaunchClaims {
  transport: CliTransport;
  row: string;
  profileId: string;
  model: string;
  effort: string;
  harnessVersion: string;
  origin: "actor";
  episodeId: string;
}
export interface CliActorObservation {
  launch: CliLaunchClaims;
  result?: WorkerResult | WriterResult;
  failure?: string;
}
export function assertCliActorSpec(
  value: unknown,
): asserts value is CliActorSpec {
  const v = value as CliActorSpec;
  if (
    !v ||
    typeof v !== "object" ||
    Array.isArray(v) ||
    Object.keys(v).some((k) => !["transport", "request"].includes(k)) ||
    !Object.hasOwn(DETACHED_LAUNCH_ROWS, v.transport) ||
    !v.request
  )
    throw new Error("invalid CLI actor declaration");
  if (isWriterRequest(v.request)) validateWriterRequest(v.request);
  else validateRequest(v.request);
}
export function cliActorRequest(spec: CliActorSpec, episodeId: string) {
  return { ...spec.request, episodeId };
}
export function assertCliObservation(
  value: unknown,
  spec: CliActorSpec,
  episodeId: string,
): asserts value is CliActorObservation {
  const v = value as CliActorObservation;
  const launch = v?.launch;
  if (
    !v ||
    !launch ||
    Object.keys(v).some((k) => !["launch", "result", "failure"].includes(k)) ||
    Object.keys(launch).some(
      (k) =>
        ![
          "transport",
          "row",
          "profileId",
          "model",
          "effort",
          "harnessVersion",
          "origin",
          "episodeId",
        ].includes(k),
    ) ||
    launch.transport !== spec.transport ||
    launch.row !== DETACHED_LAUNCH_ROWS[spec.transport].row ||
    launch.profileId !== spec.request.profile.profileId ||
    launch.model !== spec.request.model ||
    launch.effort !== spec.request.effort ||
    launch.origin !== "actor" ||
    launch.episodeId !== episodeId ||
    typeof launch.harnessVersion !== "string" ||
    !launch.harnessVersion ||
    (v.result === undefined) === (v.failure === undefined)
  )
    throw new Error("invalid CLI actor observation");
  if (
    v.failure !== undefined &&
    ![
      "model-unavailable",
      "transport-failed",
      "interrupted",
      "invalid-result",
      "deadline-exceeded",
      "output-limit",
      "profile-refused",
      "supervisor-lost",
    ].includes(v.failure)
  )
    throw new Error("invalid CLI failure code");
  const request = cliActorRequest(spec, episodeId);
  if (v.result !== undefined) {
    if (isWriterRequest(request)) parseStoredWriterResult(v.result, request);
    else parseWorkerResult(v.result, request);
  }
}

import { fork } from "node:child_process";
import { fileURLToPath } from "node:url";
import type { ActorAdapter, ActorResult, ActorSpec } from "./actor-contract.js";
import { assertActorSpec } from "./actor-contract.js";
import {
  DETACHED_LAUNCH_ROWS,
  cliActorRequest,
  type CliActorSpec,
  type CliLaunchClaims,
} from "./cli-actor-contract.js";
import { WorkerFailure } from "./worker-protocol.js";
import {
  ClaudeCliPrintWorkOrderTransport,
  CodexCliExecWorkOrderTransport,
  runWorkerProcess,
  type ProcessRunner,
} from "./worker-transport.js";

export interface CliActorContext {
  residentStore: string;
  episodeId: string;
}
const emptyDigest =
  "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
export const actorFailure = (reason: string): ActorResult => ({
  exitCode: null,
  signal: null,
  stdoutSha256: emptyDigest,
  firstLine: "",
  verified: false,
  reason,
});
function claims(
  spec: CliActorSpec,
  context: CliActorContext,
  harnessVersion: string,
): CliLaunchClaims {
  return {
    transport: spec.transport,
    row: DETACHED_LAUNCH_ROWS[spec.transport].row,
    profileId: spec.request.profile.profileId,
    model: spec.request.model,
    effort: spec.request.effort,
    harnessVersion,
    origin: "actor",
    episodeId: context.episodeId,
  };
}
/** Used by the disposable supervisor in production and by process doubles. */
export function startCliEpisode(
  spec: CliActorSpec,
  context: CliActorContext,
  runner: ProcessRunner = runWorkerProcess,
  version?: string,
) {
  const stamped: ProcessRunner = (launch) =>
    runner({
      ...launch,
      resident: { store: context.residentStore, episodeId: context.episodeId },
    });
  const transport =
    spec.transport === "claude-cli-print"
      ? new ClaudeCliPrintWorkOrderTransport(stamped, version)
      : new CodexCliExecWorkOrderTransport(stamped, version);
  const launch = claims(spec, context, transport.harnessVersion);
  const failed = (error: unknown): ActorResult => ({
    ...actorFailure("worker-failed"),
    worker: {
      launch,
      failure: error instanceof WorkerFailure ? error.code : "transport-failed",
    },
  });
  try {
    const dispatched = transport.dispatch(
      cliActorRequest(spec, context.episodeId),
      Date.now,
    );
    return {
      kill: dispatched.kill,
      completed: Promise.all([dispatched.receipt, dispatched.completed]).then(
        ([, result]): ActorResult => ({
          ...actorFailure("worker-result"),
          exitCode: 0,
          worker: { launch, result },
        }),
        failed,
      ),
    };
  } catch (error) {
    return { kill: () => {}, completed: Promise.resolve(failed(error)) };
  }
}
export function cliWorkerAdapter(
  options: {
    rows?: Readonly<
      Record<string, { row: string; label: string; reason: string }>
    >;
    runner?: ProcessRunner;
    version?: string;
  } = {},
): ActorAdapter {
  const rows = options.rows ?? DETACHED_LAUNCH_ROWS;
  return {
    kind: "cli-worker",
    available(spec?: ActorSpec) {
      if (!spec?.worker) return "cli-worker needs a declared request";
      const row = rows[spec.worker.transport];
      return row?.label === "observed"
        ? null
        : `${row?.row ?? DETACHED_LAUNCH_ROWS[spec.worker.transport].row}: ${row?.label ?? "unavailable"}; ${row?.reason ?? "detached launch row missing"}`;
    },
    run(spec, context) {
      assertActorSpec(spec);
      if (!context || !spec.worker)
        throw new Error("CLI actor requires resident context");
      const unavailable = this.available(spec);
      if (unavailable) throw new Error(unavailable);
      if (options.runner)
        return startCliEpisode(
          spec.worker,
          context,
          options.runner,
          options.version,
        );
      const child = fork(
        fileURLToPath(new URL("./cli-episode.js", import.meta.url)),
        [],
        {
          execArgv: [],
          stdio: ["ignore", "ignore", "ignore", "ipc"],
        },
      );
      let observed: ActorResult | undefined;
      const completed = new Promise<ActorResult>((resolve) => {
        child.on("message", (value) => {
          observed = value as ActorResult;
        });
        child.on("error", () => {});
        child.on("close", () =>
          resolve(
            observed ?? {
              ...actorFailure("worker-failed"),
              worker: {
                launch: claims(spec.worker!, context, "unknown"),
                failure: "supervisor-lost",
              },
            },
          ),
        );
      });
      child.send({ spec: spec.worker, context });
      return {
        completed,
        kill: () => {
          if (child.connected) child.send({ kill: true });
        },
      };
    },
  };
}

// The supervising process owns the detached CLI group. Resident death closes
// IPC and kills that group; the next resident records the unobserved episode lost.
import { startCliEpisode, type CliActorContext } from "./cli-actor.js";
import { assertCliActorSpec, type CliActorSpec } from "./cli-actor-contract.js";
let active: ReturnType<typeof startCliEpisode> | undefined;
process.on("disconnect", () => {
  if (active) active.kill();
  else process.exit(1);
});
process.on(
  "message",
  (message: {
    kill?: boolean;
    spec: CliActorSpec;
    context: CliActorContext;
  }) => {
    if (message.kill) {
      active?.kill();
      return;
    }
    if (active) return;
    assertCliActorSpec(message.spec);
    active = startCliEpisode(message.spec, message.context);
    void active.completed.then((result) => {
      if (process.connected)
        process.send!(result, () => {
          process.disconnect?.();
          process.exit(0);
        });
      else process.exit(0);
    });
  },
);

/** Human decisions are durable inputs, never model completions. */
export interface HandoffQuestion {
  workOrderId: string;
  question: string;
  options: { id: string; label: string }[];
  evidenceRefs: string[];
}
export interface HandoffPacket extends HandoffQuestion {
  episodeId: string;
}
const text = (v: unknown, max: number): v is string =>
  typeof v === "string" &&
  v.trim().length > 0 &&
  v.length <= max &&
  !/[\u0000-\u001f\u007f]/u.test(v);
export function assertHandoffQuestion(
  value: unknown,
): asserts value is HandoffQuestion {
  const v = value as HandoffQuestion;
  if (
    !v ||
    typeof v !== "object" ||
    Array.isArray(v) ||
    Object.keys(v).some(
      (k) =>
        ![
          "workOrderId",
          "question",
          "options",
          "evidenceRefs",
          "episodeId",
        ].includes(k),
    ) ||
    !text(v.workOrderId, 256) ||
    !text(v.question, 2000) ||
    !Array.isArray(v.options) ||
    v.options.length < 2 ||
    v.options.length > 10 ||
    v.options.some(
      (o) =>
        !o ||
        typeof o !== "object" ||
        Object.keys(o).some((k) => !["id", "label"].includes(k)) ||
        !text(o.id, 100) ||
        !text(o.label, 1000),
    ) ||
    new Set(v.options.map((o) => o.id)).size !== v.options.length ||
    !Array.isArray(v.evidenceRefs) ||
    !v.evidenceRefs.length ||
    v.evidenceRefs.length > 100 ||
    v.evidenceRefs.some((ref) => !text(ref, 1000))
  )
    throw new Error("invalid human handoff question");
}
export function assertHandoffPacket(
  value: unknown,
): asserts value is HandoffPacket {
  assertHandoffQuestion(value);
  if (
    !("episodeId" in value) ||
    typeof value.episodeId !== "string" ||
    !/^[a-zA-Z0-9_-]+$/u.test(value.episodeId)
  )
    throw new Error("invalid human handoff episode");
}

import {
  closeSync,
  fsyncSync,
  mkdirSync,
  openSync,
  readFileSync,
  realpathSync,
  writeFileSync,
  linkSync,
  unlinkSync,
} from "node:fs";
import { randomUUID } from "node:crypto";
import { join } from "node:path";
import { canonicalStringify } from "@dotln/compiler";
