      ...(discovery ? { discovery } : {}),
      exitCode,
      signal,
      stdoutSha256,
      firstLine,
      verified: exitCode === 0 && reason === "completed" && matches,
      reason:
        exitCode === 0 && reason === "completed" && !matches
          ? "output-verification-failed"
          : reason,
    };
    if (process.connected)
      process.send!(result, () => {
        process.disconnect?.();
        process.exit(0);
      });
