  private record(type: string, payload: unknown): Event {
    const step = this.driver.feed({
      schemaVersion: 1,
      type,
      occurredAt: this.now(),
      actorId: SOURCE_CHANGE_HOST,
      workstreamId: this.workstreamId,
      episodeId: this.logicalEpisode,
      correlationId: this.command.commandId,
