          { ...this.command.intent, effect },
          this.options.authorityEnvelope,
          {
            now: this.now(),
            actorId: SOURCE_CHANGE_HOST,
            workstreamId: this.workstreamId,
            episodeId: this.logicalEpisode,
            decisionIndex: 1,
            intentIndex: 0,
            evidence: this.options.authorityEvidence,
