    if (
      present(directory) &&
      (lstatSync(directory).isSymbolicLink() ||
        !lstatSync(directory).isDirectory())
    )
      throw new Error("source-change scratch path is not an owned directory");
    mkdirSync(directory, { recursive: true });
    if (present(this.messagePath)) {
      this.checkMessage();
