  }
  checkMessage(): void {
    if (
      lstatSync(dirname(this.messagePath)).isSymbolicLink() ||
      !lstatSync(this.messagePath).isFile() ||
      lstatSync(this.messagePath).isSymbolicLink() ||
      readFileSync(this.messagePath, "utf8") !== this.options.commitMessage
