  const result = fields({});
  for (const key of /** @type {(keyof Usage)[]} */ (Object.keys(result))) {
    const numbers = values.map((value) => value[key]);
    result[key] =
      numbers.length && numbers.every((value) => value !== null)
        ? numbers.reduce((total, value) => (total ?? 0) + (value ?? 0), 0)
        : null;
