/** A labeled behavior dependency projection, never a claim of raw manifest bytes. */
export function feedbackSourceFile(path: string, contents: string) {
  if (!["package-lock.json", "packages/skeleton/package.json"].includes(path))
    return { path, contents };
  const object = (value: unknown): value is Record<string, unknown> =>
    value !== null && typeof value === "object" && !Array.isArray(value);
  const value: unknown = JSON.parse(contents);
  if (!object(value))
    throw new Error("feedback package source must be an object");
  const omitted = ["/version", "/license"];
  delete value.version;
  delete value.license;
  if (path === "package-lock.json") {
    if (!object(value.packages))
      throw new Error("feedback lockfile requires a packages object");
    // npm records each linked workspace with its resolved lockfile entry.
    // Keep unlinked package metadata and registry dependencies in the subject.
    const workspaces = new Set([""]);
    for (const entry of Object.values(value.packages)) {
      if (!object(entry))
        throw new Error("feedback package lock entry must be an object");
      if (
        entry.link === true &&
        typeof entry.resolved === "string" &&
        Object.hasOwn(value.packages, entry.resolved)
      )
        workspaces.add(entry.resolved);
    }
    for (const workspace of [...workspaces].sort()) {
      const entry = value.packages[workspace];
      if (entry === undefined) continue;
      if (!object(entry))
        throw new Error("feedback workspace lock entry must be an object");
      delete entry.version;
      delete entry.license;
      const pointer = workspace.replaceAll("/", "~1");
      omitted.push(
        `/packages/${pointer}/version`,
        `/packages/${pointer}/license`,
      );
    }
  }
  return {
    path: `.feedback-source/${path}`,
    contents:
      canonicalStringify({
        projection: "feedback-package-projection-v1",
        sourcePath: path,
        omitted,
        value,
      }) + "\n",
  };
}

export function readFeedbackSource(root: string) {
  const physical = realpathSync(root);
  const gitRoot = execFileSync("git", ["rev-parse", "--show-toplevel"], {
    cwd: physical,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
    timeout: 5000,
  }).trim();
  if (realpathSync(gitRoot) !== physical)
    throw new Error("feedback requires the Git root");
  const files = FEEDBACK_SOURCE_PATHS.map((path) => {
    const absolute = resolve(physical, path);
    if (realpathSync(absolute) !== absolute || !lstatSync(absolute).isFile())
      throw new Error("feedback source must be a contained regular file");
    return feedbackSourceFile(path, readFileSync(absolute, "utf8"));
  });
  return { files, subject: feedbackContentHash(canonicalStringify(files)) };
}
export function feedbackContextAccounting(
  program: CompiledFeedback,
  baseline: {
    readonly files: readonly {
      readonly lines: number;
      readonly bytes: number;
    }[];
  },
) {
  const size = (value: string) => ({
    files: 1,
    lines: value.split("\n").length - 1,
    bytes: Buffer.byteLength(value, "utf8"),
  });
  const prose =
    program.units.map((unit) => unit.proseEquivalent).join("\n") + "\n";
  const residue =
    `Feedback policy ${program.policyHash}: executable units use host predicates; prose remains role guidance and Stop advises.\n` +
    program.units
      .filter((unit) => unit.mechanism.kind === "prose")
      .map((unit) => unit.proseEquivalent)
      .join("\n") +
    "\n";
  const commonBaseline = {
    files: baseline.files.length,
    lines: baseline.files.reduce((sum, file) => sum + file.lines, 0),
    bytes: baseline.files.reduce((sum, file) => sum + file.bytes, 0),
  };
  const proseEquivalent = size(prose),
    compiledResidue = size(residue);
  return {
    method:
      "WO-004 UTF-8 instruction-file bytes and physical lines; matched common baseline plus one task-local projection",
    baselineRef:
      "docs/discovery/environment.json#claudeCode.startupContext.files",
    commonBaseline,
    proseEquivalent,
    compiledResidue,
    beforeBytes: commonBaseline.bytes + proseEquivalent.bytes,
    afterBytes: commonBaseline.bytes + compiledResidue.bytes,
    savedBytes: proseEquivalent.bytes - compiledResidue.bytes,
    limits:
      "Counterfactual instruction projection, not effective-session tokens or total workflow cost. Verifier source/evidence context and tool schemas are outside this matched comparison.",
  };
}
export function runFeedbackRegressions(
  root: string,
  program: CompiledFeedback,
) {
  const source = readFeedbackSource(root);
  const fixture = "packages/skeleton/dist/test/feedback-fixtures.test.js";
  const run = (unitId: string, removed: boolean) => {
    const unit = program.units.find((row) => row.unitId === unitId)!;
    const name = unit.regressionFixtures[0]!;
    const env = { ...process.env };
    delete env.DOTLN_FEEDBACK_ABLATE;
    // An independent test subprocess must not inherit its parent's test-runner IPC mode.
    delete env.NODE_TEST_CONTEXT;
    if (removed) env.DOTLN_FEEDBACK_ABLATE = unitId;
    const args = [
      "--test",
      "--test-reporter=tap",
      `--test-name-pattern=^${name}$`,
      unit.version === 1
        ? fixture
        : "packages/skeleton/dist/test/feedback-v2.test.js",
    ];
    const result = spawnSync(process.execPath, args, {
      cwd: root,
      env,
      encoding: "utf8",
      timeout: 30_000,
      maxBuffer: 1_000_000,
    });
    if (result.error || result.signal)
      throw new Error("feedback regression subprocess unavailable");
    const output = result.stdout;
    const passed = Number(output.match(/^# pass (\d+)$/mu)?.[1] ?? -1);
    const failed = Number(output.match(/^# fail (\d+)$/mu)?.[1] ?? -1);
    const expected = removed
      ? result.status === 1 &&
        passed === 0 &&
        failed === 1 &&
        output.includes(`- ${name}`) &&
        /code: 'ERR_ASSERTION'/u.test(output)
      : result.status === 0 && passed === 1 && failed === 0;
    if (!expected)
      throw new Error(
        `feedback fixture gate failed: ${unitId} ${removed ? "removed" : "present"}`,
      );
    return {
      command: `node ${args.join(" ")}`,
      mechanism: removed ? "removed" : "present",
      exitCode: result.status,
      passed,
      failed,
      captured: output
        .split("\n")
        .filter(
          (line) =>
            new RegExp(`^(?:not )?ok \\d+ - ${name}$`, "u").test(line) ||
            /^\s+(?:code: 'ERR_ASSERTION'|operator: )/u.test(line) ||
            /^# (?:pass|fail) /u.test(line),
        ),
    };
  };
  const fixtures = program.units.map((unit) => ({
    unitId: unit.unitId,
    present: run(unit.unitId, false),
    removed: run(unit.unitId, true),
  }));
  if (readFeedbackSource(root).subject !== source.subject)
    throw new Error("feedback source changed during audit");
  const baseline = JSON.parse(
    readFileSync(resolve(root, "docs/discovery/environment.json"), "utf8"),
  );
  const context = feedbackContextAccounting(
    program,
    baseline.claudeCode.startupContext,
  );
  if (context.savedBytes <= 0)
    throw new Error("feedback context did not decrease");
  const observations: FeedbackObservation[] = fixtures.map((fixture) => ({
    unitId: fixture.unitId,
    episodeId: `regression_${fixture.unitId}`,
    source: "fixture",
    activated: true,
    prevented:
      program.units.find((unit) => unit.unitId === fixture.unitId)
        ?.enforcement === "hard",
    falseActivation: false,
    overridden: false,
  }));
  return {
    contractVersion: "feedback-audit-v1",
    policyHash: program.policyHash,
    subject: source.subject,
    fixtures,
    context,
    maturityMethod:
      "One isolated present/removal fixture per unit. Hard units count prevention; prose delivery and advisory violations do not claim behavioral prevention. Fixtures are not a population estimate.",
    maturity: feedbackMaturity(program, observations),
  };
}
export type FeedbackAuditReport = ReturnType<typeof runFeedbackRegressions>;

import childProcess from "node:child_process";
import { appendFileSync, readFileSync } from "node:fs";
import { availableParallelism, loadavg } from "node:os";

// A scheduler declaration, not a host-speed detector. The factor includes two
// times the measured solo baseline per scheduler slot. Ordinary host commands
// retain their existing finite bounds. See WO-128's deadline inventory.
/** @param {NodeJS.ProcessEnv} [env] */
export function gateLoad(env = process.env) {
  const name = env.DOTLN_GATE_LOAD_CLASS;
  if (!name) return { name: "standalone", concurrency: 1, factor: 1 };
  const concurrency = Number(env.DOTLN_GATE_CONCURRENCY);
  if (
    !["shared", "isolated"].includes(name) ||
    !Number.isInteger(concurrency) ||
    concurrency < 1 ||
    concurrency > 4 ||
    (name === "isolated" && concurrency !== 1) ||
    Number(env.DOTLN_GATE_LOAD_FACTOR) !== concurrency * 2
  )
    throw new Error("Invalid scheduler deadline load declaration");
  return { name, concurrency, factor: concurrency * 2 };
}

/** Preserve the standalone bound; only measured work can derive a larger one.
 * @param {number} baselineMs @param {number} minimumMs
 * @param {NodeJS.ProcessEnv} [env] */
export function deadlineLimit(baselineMs, minimumMs, env = process.env) {
  if (
    !Number.isFinite(baselineMs) ||
    !Number.isFinite(minimumMs) ||
    !(baselineMs > 0) ||
    !(minimumMs > 0)
  )
    throw new Error(
      "Deadline baseline and minimum must be positive and finite",
    );
  const load = gateLoad(env);
  return load.name === "standalone"
    ? minimumMs
    : Math.ceil(Math.max(minimumMs, baselineMs * load.factor));
}

/** @param {string} value */
const safeName = (value) =>
  /^[a-zA-Z0-9_./:@-]{1,240}$/.test(value) ? value : "unavailable";

/** Numeric diagnostic only: no command, environment value, process identity,
 * arbitrary stack, source contents or private path is retained.
 * @param {string} site @param {number} timeoutMs
 * @param {{env?: NodeJS.ProcessEnv, now?: () => number}} [options] */
export function startDeadline(site, timeoutMs, options = {}) {
  if (!Number.isFinite(timeoutMs) || timeoutMs <= 0)
    throw new Error("Deadline must be a positive finite duration");
  const env = options.env ?? process.env;
  const load = gateLoad(env);
  const now = options.now ?? (() => performance.now());
  const started = now();
  const startedAt = new Date().toISOString();
  let finished = false;
  const finish = (hit = false) => {
    const durationMs = Math.max(0, now() - started);
    let peers = [];
    let peerObservation = "unavailable";
    if (env.DOTLN_GATE_PEER_FILE) {
      try {
        const observed = JSON.parse(
          readFileSync(env.DOTLN_GATE_PEER_FILE, "utf8"),
        );
        if (
          Array.isArray(observed.tasks) &&
          observed.tasks.every(
            /** @param {unknown} name */ (name) => typeof name === "string",
          )
        ) {
          peers = observed.tasks
            .filter(
              /** @param {string} name */ (name) =>
                name !== env.DOTLN_GATE_TASK,
            )
            .map(safeName);
          peerObservation = "scheduler-current";
        }
      } catch {
        // Never infer an empty peer set when the current observation is absent.
      }
    }
    const hostLoadPerCpu = (loadavg()[0] ?? 0) / availableParallelism();
    const record = {
      site: safeName(site),
      task: safeName(env.DOTLN_GATE_TASK ?? "standalone"),
      timeoutMs,
      durationMs,
      startedAt,
      finishedAt: new Date().toISOString(),
      hit,
      loadClass: load.name,
      concurrency: load.concurrency,
      loadFactor: load.factor,
      concurrentTasks: peers,
      peerObservation,
      hostLoadPerCpu,
      classification: !hit
        ? "completed"
        : (peerObservation === "scheduler-current" &&
              peers.length >= load.concurrency) ||
            hostLoadPerCpu > 2
          ? "outside-declared-load"
          : "deadline-hit-cause-unestablished",
    };
    if (!finished) {
      finished = true;
      if (
        env.DOTLN_GATE_DEADLINE_LOG &&
        (hit || env.DOTLN_GATE_MEASURE_DEADLINES === "1")
      )
        appendFileSync(
          env.DOTLN_GATE_DEADLINE_LOG,
          JSON.stringify(record) + "\n",
          { mode: 0o600 },
        );
    }
    return record;
  };
  return {
    timeoutMs,
    finish,
    check() {
      if (now() - started < timeoutMs) return;
      const record = finish(true);
      throw new Error(
        `Deadline ${record.site} hit after ${record.durationMs.toFixed(1)} ms (bound ${timeoutMs} ms; ${record.classification})`,
      );
    },
  };
}

/** Stable source family, including built/pinned runtime copies. Line numbers
 * move on compilation and are deliberately not used as a baseline identity.
 * @param {string} operation @param {number} timeout */
function callerSite(operation, timeout) {
  const frames = new Error().stack?.split("\n").slice(2) ?? [];
  for (const frame of frames) {
    const match = /\/(scripts|packages|corpus)\/(.+?):\d+:\d+/.exec(frame);
    if (!match || match[2]?.split("/").at(-1) === "gate-deadlines.mjs")
      continue;
    const path = `${match[1]}/${match[2]}`
      .replace("/dist/", "/")
      .replace(/\.js$/, ".ts");
    return `${path}:${operation}:${timeout}`;
  }
  return `inline:${operation}:${timeout}`;
}

// Explicit imports preserve Node's normal startup environment and reuse rule.
// Untimed calls and standalone calls preserve the original API and options.
/** @param {"spawnSync" | "execFileSync"} operation @param {any[]} args */
function observedSync(operation, args) {
  const index = args.findIndex(
    (arg, i) => i > 0 && arg && typeof arg === "object" && !Array.isArray(arg),
  );
  const options = index >= 0 ? args[index] : null;
  const timeout = options?.timeout;
  const run = /** @type {(...values: any[]) => any} */ (
    childProcess[operation]
  );
  if (!timeout) return run(...args);
  const deadline = startDeadline(callerSite(operation, timeout), timeout);
  let hit = false;
  try {
    const result = run(...args);
    hit = result?.error?.code === "ETIMEDOUT";
    return result;
  } catch (error) {
    hit = /** @type {NodeJS.ErrnoException} */ (error).code === "ETIMEDOUT";
    throw error;
  } finally {
    deadline.finish(hit);
  }
}

export const observedSpawnSync = /** @type {typeof childProcess.spawnSync} */ (
  (...args) => observedSync("spawnSync", args)
);
export const observedExecFileSync =
  /** @type {typeof childProcess.execFileSync} */ (
    (...args) => observedSync("execFileSync", args)
  );

/** Async spawn's native timeout does not expose which signal source fired.
 * Own that same timer so a deadline hit is distinguished from a caller kill. */
/** @param {any[]} args */
function observedAsync(...args) {
  const run =
    /** @type {(...args: any[]) => import("node:child_process").ChildProcess} */ (
      childProcess.spawn
    );
  const index = args.findIndex(
    (arg, i) => i > 0 && arg && typeof arg === "object" && !Array.isArray(arg),
  );
  const options = index >= 0 ? args[index] : null;
  const timeout = options?.timeout;
  if (!timeout) return run(...args);
  const deadline = startDeadline(callerSite("spawn", timeout), timeout);
  const next = [...args];
  next[index] = { ...options, timeout: 0 };
  const child = run(...next);
  const timer = setTimeout(() => {
    deadline.finish(true);
    child.kill(options.killSignal ?? "SIGTERM");
  }, timeout);
  child.once("close", () => {
    clearTimeout(timer);
    deadline.finish();
  });
  return child;
}
export const observedSpawn = /** @type {typeof childProcess.spawn} */ (
  observedAsync
);

