      criterionId: criterion.criterionId,
      checkId: criterion.requiredChecks[0]!,
      claimType: criterion.claimType,
      source: criterion.evidenceSource,
      subjectRevision: revision,
      codeSurfaces: criterion.codeSurfaces,
      automatedTest:
        index === 0
