export interface RepairHostOptions {
  readonly store: WorkerStore;
  readonly original: RepairOriginal;
  readonly grants?: RepairGrants;
  readonly baseline: VerificationSubject;
  readonly subject: VerificationSubject;
  readonly snapshotPath: string;
  /** Retained child stores and verification copies, outside target worktrees. */
  readonly directory: string;
  readonly source: Pick<
    SourceChangeHostOptions,
    | "authorityEvidence"
    | "artifactIdentity"
    | "worktreeParent"
    | "launchpadCheckout"
    | "model"
    | "effort"
    | "transport"
  >;
  readonly verifier: {
    readonly transport: WorkOrderTransport<EvidenceWorkerRequest>;
    readonly model: string;
    readonly effort: string;
  };
  readonly now?: () => number;
  readonly onEvent?: (event: Event) => void;
  /** Fault injection after durable child receipt, before parent observation. */
  readonly afterRepairCommit?: () => void;
  readonly afterSnapshotPrepared?: () => void;
}

/** Host effects are selected by the persisted executable program, not a retry loop. */
export class RepairHost {
  private runtime: RuntimeState = initialState();
  private log = "";
  private lastDecision?: Decision<RuntimeState>;
  readonly now: () => number;
  readonly workstreamId: string;
  constructor(readonly options: RepairHostOptions) {
    this.now = options.now ?? Date.now;
    this.workstreamId = `repair_${repairHash(options.original.workOrder.workOrderId).slice(8)}`;
  }
  get state(): RepairState {
    return this.runtime.repair as unknown as RepairState;
  }
  private opening(): Record<string, unknown> {
    const shell = {
      workstreamId: this.workstreamId,
      round: 0,
      finding: null,
    } as RepairState;
    return {
      original: this.options.original,
      grants: this.options.grants ?? noRepairGrants,
      baseline: this.options.baseline,
      subject: this.options.subject,
      continuation: repairVerificationProgram(shell),
      host: {
        directory: this.options.directory,
        snapshotPath: this.options.snapshotPath,
        source: {
          ...this.options.source,
          transport: {
            name: this.options.source.transport.name,
            harnessVersion: this.options.source.transport.harnessVersion,
          },
        },
        verifier: {
          ...this.options.verifier,
          transport: {
            name: this.options.verifier.transport.name,
            harnessVersion: this.options.verifier.transport.harnessVersion,
          },
        },
      },
    };
  }
  private restore = (): void => {
    this.log = this.options.store.read();
    const events = decodeLog(this.log);
    const opening = events.find((e) => e.type === "RepairOpened");
    if (opening && !repairEqual(opening.payload, this.opening()))
      throw new Error("repair recovery request drift");
    if (
      events.some(
        (e) =>
          e.actorId !== REPAIR_HOST || e.workstreamId !== this.workstreamId,
      )
    )
      throw new Error("repair store contains foreign events");
    this.runtime = replay(
      initialState(),
      events,
      seiriReactor,
      {},
      projectRuntimeEnvironment,
    ).state;
  };
  private feed(type: string, payload: unknown, correlationId?: string): Event {
    const draft: EventDraft = {
      schemaVersion: 1,
      type,
      occurredAt: this.now(),
      actorId: REPAIR_HOST,
      workstreamId: this.workstreamId,
      ...(correlationId ? { correlationId } : {}),
      payload: payload as JsonValue,
    };
    const appended = appendEvent(this.log, draft);
    const decision = seiriReactor(this.runtime, appended.event, {
      now: draft.occurredAt,
      rngState: 0,
      predicates: {},
    });
    this.options.store.append(appended.event);
    this.log = appended.log;
    this.runtime = decision.state;
    this.lastDecision = decision;
    this.options.onEvent?.(appended.event);
    return appended.event;
  }
  sourceHost(): SourceChangeHost {
    const order = this.state.order;
    if (!order) throw new Error("repair has no derived order");
    return new SourceChangeHost({
      ...this.options.source,
      store: new WorkerStore(
        join(this.options.directory, `source-${order.round}`),
      ),
      workOrder: order.workOrder,
      authorityEnvelope: order.authorityEnvelope,
      executionBaseCommit: order.executionBaseCommit,
      repairContext: {
        contract: order.contract,
        contractHash: order.contractHash,
        finding: order.finding,
        tests: order.tests,
        grantIds: order.grantIds,
        round: order.round,
      } as unknown as JsonValue,
      branch: `dotln-repair-${repairHash([this.workstreamId, order.round]).slice(8)}`,
      surfaces: order.surfaces,
      testCommand: order.tests[0]!.command,
      commitMessage: `Repair ${order.finding.findingId}\n`,
      now: this.now,
    });
  }
  private async verify(command: Command): Promise<void> {
    const state = this.state;
    const store = new WorkerStore(
      join(this.options.directory, `verification-${state.round}`),
    );
    const stream = `${this.workstreamId}_verify_${state.round}`;
    const saved = decodeLog(store.read()).find(
      (e) => e.type === "RepairSnapshotPrepared",
    );
    let prepared = saved?.payload as unknown as
      { subject: VerificationSubject; snapshotPath: string } | undefined;
    let path =
      state.round === 0
        ? this.options.snapshotPath
        : (prepared?.snapshotPath ?? "");
    if (
      prepared &&
      (dirname(dirname(path)) !== this.options.directory ||
        basename(path) !== "snapshot" ||
        !new RegExp(`^snapshot-${state.round}-[0-9]+$`, "u").test(
          basename(dirname(path)),
        ))
    )
      throw new Error("repair snapshot receipt path drift");
    if (prepared)
      assertWorktreeSnapshot(
        compileVerificationTask(
          "repair_preflight",
          state.original.criteria,
          prepared.subject,
        ),
        path,
      );
    store.acquire(() =>
      preflightVerificationRecovery(
        store,
        stream,
        () => path,
        this.options.verifier.model,
        this.options.verifier.effort,
      ),
    );
    try {
      const driver = new VerificationDriver(store, stream);
      if (driver.state.next === "unopened") {
        if (state.round > 0 && !prepared) {
          // An interrupted, unpublished preparation remains inspectable. A new
          // attempt never edits or adopts its incomplete files.
          let attempt = 0;
          let directory: string;
          do {
            directory = join(
              this.options.directory,
              `snapshot-${state.round}-${attempt++}`,
            );
          } while (existsSync(directory));
          prepared = prepareWorktreeVerification({
            worktree: this.sourceHost().tree.path,
            baseCommit: state.original.workOrder.baseCommit,
            observedCommit: state.currentCommit,
            repo: state.subject.repo,
            contract: this.options.subject.snapshot!.contract,
            criteria: state.original.criteria,
            tests: state.original.tests,
            directory,
          });
          path = prepared.snapshotPath;
          driver.record("RepairSnapshotPrepared", this.now(), {
            subject: prepared.subject,
            snapshotPath: path,
          });
          this.options.afterSnapshotPrepared?.();
        }
        const subject = state.round === 0 ? state.subject : prepared!.subject;
        const capsule = compileVerificationTask(
          "repair_preflight",
          state.original.criteria,
          subject,
        );
        assertWorktreeSnapshot(capsule, path);
        driver.record("VerificationOpened", this.now(), {
          baseline: state.baseline,
          subject,
          criteria: state.original.criteria,
          implementerEpisodeId: `repair_source_${state.round}`,
          episodeNamespace: stream,
          maxRepairs: 0,
          authority: {
            authorityEnvelopeId: "repair.verifier",
            allowedEffects: ["verification.evaluate"],
            deniedEffects: ["repo.write", "repair.propose"],
            resourceLimits: { episodes: 1 },
            requiredEvidence: [],
            expiresAt: state.original.authorityEnvelope.expiresAt,
            revocationEventTypes:
              state.original.authorityEnvelope.revocationEventTypes,
          },
        });
      }
      if (!driver.state.lastResultEventId) {
        driver.persistNext(this.now());
        await new VerificationHost({
          driver,
          transport: this.options.verifier.transport,
          now: this.now,
        }).run(path, this.options.verifier.model, this.options.verifier.effort);
      }
      const events = decodeLog(driver.log);
      const result = events.find(
        (e) => e.eventId === driver.state.lastResultEventId,
      );
      if (!result)
        throw new Error("repair verification has no admitted result");
      const p = result.payload as Record<string, JsonValue>;
      const persisted = events.find((e) => e.type === "CommandPersisted")!;
      const verifierCommand = (
        persisted.payload as unknown as { command: Command }
      ).command;
      const capsule = (
        verifierCommand.intent.payload as Record<string, JsonValue>
      ).capsule;
      this.feed("RepairCommandResult", {
        commandId: command.commandId,
        result: "completed",
        capsule,
        verifierCommand,
        value: p.value,
      });
    } finally {
      store.release();
    }
  }
  async run(): Promise<RepairState> {
    this.options.store.acquire(this.restore);
    try {
      mkdirSync(this.options.directory, { recursive: true });
      if (!this.runtime.repair) this.feed("RepairOpened", this.opening());
      while (this.state.status === "running") {
        if (this.state.emission) {
          this.feed(this.state.emission.type, this.state.emission.payload);
        } else if (this.state.pending) {
          const command = this.state.pending;
          if (command.intent.effect === "repo.write")
            this.feed("RepairCommandResult", {
              commandId: command.commandId,
              result: "accepted",
            });
          else await this.verify(command);
        } else {
          this.feed("RepairTick", {});
          const intent = this.lastDecision!.intents[0];
          if (intent?.kind === "Act") {
            const kind = intent.effect === "repo.write" ? "write" : "verify";
            this.feed("RepairCommandPersisted", {
              command: repairCommand(this.state, kind),
            });
          } else if (!this.state.emission) {
            // A waiting source observation owns an already-persisted child command.
            const source = this.sourceHost();
            const outcome = await source.run();
            if (outcome.status === "refused")
              this.feed("NeedsHuman", {
                reason: "source change refused",
                offending: outcome.refusal.reason,
              });
            else {
              this.options.afterRepairCommit?.();
              const before = source.tree.effect();
              const tests = this.state.order!.tests.map((test) => {
                if (
                  !sourceChangeAuthorization(
                    { kind: "Act", effect: "shell.run", payload: {} },
                    this.state.order!.authorityEnvelope,
                    {
                      now: this.now(),
                      actorId: REPAIR_HOST,
                      workstreamId: this.workstreamId,
                      decisionIndex: this.state.round,
                      intentIndex: 0,
                      evidence: this.options.source.authorityEvidence,
                      revokedBy: decodeLog(source.options.store.read()),
                    },
                  ).authorized
                )
                  throw new Error("repair test authority expired or revoked");
                const result = runFocusedTest(source.tree.path, test.command);
                if (!repairEqual(before, source.tree.effect()))
                  throw new Error(
                    "repair reproduction changed committed source",
                  );
                return result;
              });
              this.feed(
                "SourceChangeObserved",
                { observation: outcome.observation, tests },
                repairCommand(this.state, "write").commandId,
              );
            }
          }
        }
      }
      return this.state;
    } finally {
      this.options.store.release();
    }
  }
}

import {
  canonicalStringify,
  compileLoadout,
  requireCompiled,
  type CompilationEnvironment,
  type CompiledPresencePolicy,
  type LoadoutGraph,
} from "@dotln/compiler";
import {
  authorize,
  commandId,
  type Event,
  type PredicateRegistry,
} from "@dotln/kernel";
import {
  assertActorResult,
  scriptResultVerified,
  assertActorSpec,
  type ActorSpec,
} from "./actor-contract.js";
import {
  PresenceMachine,
  presencePredicates,
  type PresenceSnapshot,
} from "./presence-machine.js";
import {
  decodePresenceObservation,
  presenceActorKey,
} from "./presence-signals.js";
import { assertHandoffPacket, type HandoffPacket } from "./handoff-contract.js";
import { isWriterRequest } from "./worker-protocol.js";

export interface ResidentConfiguration {
  graph: LoadoutGraph;
  environment: CompilationEnvironment;
  policyId: string;
  actors: Record<string, ActorSpec>;
  evidence: string[];
  heartbeatBudgetMs?: number;
}
export interface ResidentState {
  configuration: ResidentConfiguration | null;
  policy: CompiledPresencePolicy | null;
  machine: PresenceSnapshot | null;
  at: number;
  present: boolean;
  episodes: Record<string, "dispatched" | "observed" | "lost">;
  episodePhases: Record<string, string>;
  episodeGenerations: Record<string, number>;
  revokedBy: Event[];
  lastNoOp: string | null;
  lastHumanAt: number | null;
  actors: Record<
    string,
    {
      lastHeartbeatAt: number;
      status: "live" | "stalled" | "stopped";
      failureAt?: number;
      episodeId?: string;
    }
  >;
  progress: Record<string, number>;
  handoffs: Record<
    string,
    {
      packet: HandoffPacket;
      phaseId: string;
      generation: number;
      answer?: string;
    }
  >;
}
export function decodeResidentConfiguration(
  value: unknown,
): ResidentConfiguration {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("invalid resident configuration");
  const v = value as ResidentConfiguration;
  if (
    Object.keys(v).some(
      (key) =>
        ![
          "graph",
          "environment",
          "policyId",
          "actors",
          "evidence",
          "heartbeatBudgetMs",
        ].includes(key),
    ) ||
    typeof v.policyId !== "string" ||
    !v.actors ||
    typeof v.actors !== "object" ||
    Array.isArray(v.actors) ||
    !Array.isArray(v.evidence) ||
    v.evidence.some((item) => typeof item !== "string")
  )
    throw new Error("invalid resident configuration fields");
  if (
    v.heartbeatBudgetMs !== undefined &&
    (!Number.isSafeInteger(v.heartbeatBudgetMs) || v.heartbeatBudgetMs < 1)
  )
    throw new Error("invalid resident heartbeat budget");
  const program = requireCompiled(compileLoadout(v.graph, v.environment));
  const policy = program.presence?.find((p) => p.policyId === v.policyId);
  if (!policy) throw new Error("resident policy is not compiled");
  if (Object.keys(v.actors).length !== policy.phases.length)
    throw new Error("resident requires one actor per phase");
  for (const phase of policy.phases) {
    if (!Object.hasOwn(v.actors, phase.phaseId))
      throw new Error("resident phase actor is missing");
    assertActorSpec(v.actors[phase.phaseId]);
  }
  return structuredClone(v);
}
export const emptyResidentState = (): ResidentState => ({
  configuration: null,
  policy: null,
  machine: null,
  at: 0,
  present: true,
  episodes: {},
  episodePhases: {},
  episodeGenerations: {},
  revokedBy: [],
  lastNoOp: null,
  lastHumanAt: null,
  actors: {},
  progress: {},
  handoffs: {},
});
export function residentMachine(
  state: ResidentState,
  predicates: PredicateRegistry = {},
) {
  if (!state.policy || !state.machine)
    throw new Error("resident is not configured");
  return new PresenceMachine(
    state.policy,
    { ...predicates, ...presencePredicates },
    state.machine,
  );
}
export function residentEpisodeId(
  machine: PresenceMachine,
  dueAt: number,
): string {
  return commandId(
    "resident",
    canonicalStringify([
      machine.compiled.policyId,
      machine.state,
      machine.phase()!.cadence,
      dueAt,
      machine.generation,
    ]),
    0,
    0,
  ).replace("cmd_", "script_");
}
export const residentEventTypes = [
  "ResidentConfigured",
  "ClockSampled",
  "ScriptEpisodeDispatched",
  "ScriptEpisodeObserved",
  "ScriptEpisodeLost",
  "ScriptEpisodeRefused",
  "ActorUnavailable",
  "OperatorPresenceObserved",
  "HandoffRequested",
  "HandoffAnswered",
  "CliWorkerObserved",
] as const;

function expireActorHeartbeats(state: ResidentState) {
  const budget = state.configuration?.heartbeatBudgetMs ?? 30000;
  for (const actor of Object.values(state.actors)) {
    if (actor.status === "live" && state.at - actor.lastHeartbeatAt >= budget) {
      actor.status = "stalled";
      actor.failureAt = actor.lastHeartbeatAt + budget;
    }
  }
}

export function residentRefusal(
  state: ResidentState,
  machine: PresenceMachine,
): string | null {
  const phase = machine.phase()!;
  const spec = state.configuration!.actors[phase.phaseId]!;
  const orderId =
    spec.worker?.request.workOrder.workOrderId ?? spec.handoff?.workOrderId;
  if (
    orderId &&
    Object.values(state.handoffs).some(
      (h) => h.packet.workOrderId === orderId && h.answer === undefined,
    )
  )
    return "work order is waiting for a human handoff answer";
  if (!phase.scope.surfaces.includes(spec.surface))
    return "actor surface is outside phase scope";
  const limits: Record<string, number> = { ...phase.scope.budget };
  for (const [resource, amount] of Object.entries(phase.scope.changeSize))
    limits[resource] = Math.min(limits[resource] ?? Infinity, amount);
  if (
    Object.keys(limits).some((key) => !Object.hasOwn(spec.resources, key)) ||
    Object.entries(spec.resources).some(
      ([resource, amount]) =>
        amount > (limits[resource] ?? 0) ||
        amount >
          (Object.hasOwn(phase.effectiveEnvelope.resourceLimits, resource)
            ? phase.effectiveEnvelope.resourceLimits[resource]!
            : 0),
    )
  )
    return "actor resource reservation exceeds phase scope or authority budget";
  const authorization = authorize(
    { kind: "Act", effect: spec.effect, payload: {} },
    phase.effectiveEnvelope,
    {
      now: state.at,
      actorId: spec.kind,
      workstreamId: "resident",
      decisionIndex: 0,
      intentIndex: 0,
      evidence: state.configuration!.evidence,
      revokedBy: state.revokedBy,
      state: machine.projected(),
      predicateEnv: { rngState: 0, predicates: machine.predicates },
    },
  );
  if (spec.worker) {
    const request = spec.worker.request;
    const envelope = phase.effectiveEnvelope;
    const effects = [...request.workOrder.allowedOperations];
    if (isWriterRequest(request)) {
      const authority = request.authorityEnvelope;
      if (
        authority.expiresAt > envelope.expiresAt ||
        Object.entries(authority.resourceLimits).some(
          ([key, amount]) => amount > (spec.resources[key] ?? 0),
        ) ||
        envelope.requiredEvidence.some(
          (e) => !authority.requiredEvidence.includes(e),
        ) ||
        envelope.revocationEventTypes.some(
          (e) => !authority.revocationEventTypes.includes(e),
        ) ||
        authority.revocationEventTypes.some(
          (e) => !envelope.revocationEventTypes.includes(e),
        ) ||
        (authority.revocationConditions?.length ?? 0) > 0 ||
        (envelope.revocationConditions?.length ?? 0) > 0
      )
        return "worker authority exceeds or cannot represent the resident phase";
      effects.push(
        ...authority.allowedEffects.filter((e) => !effects.includes(e)),
      );
    }
    for (const effect of effects) {
      for (const candidate of isWriterRequest(request)
        ? [envelope, request.authorityEnvelope]
        : [envelope]) {
        const check = authorize(
          { kind: "Act", effect, payload: {} },
          candidate,
          {
            now: state.at,
            actorId: spec.kind,
            workstreamId: "resident",
            decisionIndex: 0,
            intentIndex: 0,
            evidence: state.configuration!.evidence,
            revokedBy: state.revokedBy,
            state: machine.projected(),
            predicateEnv: { rngState: 0, predicates: machine.predicates },
          },
        );
        if (!check.authorized)
          return "worker operations exceed the resident phase authority";
      }
    }
  }
  return authorization.authorized ? null : authorization.refusal.payload.reason;
}

export function foldResidentEvent(
  previous: ResidentState | undefined,
  event: Event,
  predicates: PredicateRegistry,
): ResidentState {
  const state = structuredClone({ ...emptyResidentState(), ...previous });
  const payload = event.payload as Record<string, unknown>;
  if (!payload || typeof payload !== "object" || Array.isArray(payload))
    throw new Error("invalid resident event payload");
  if (event.type === "ResidentConfigured") {
    const configuration = decodeResidentConfiguration(payload["configuration"]);
    if (state.configuration) {
      if (
        canonicalStringify(configuration) !==
        canonicalStringify(state.configuration)
      )
        throw new Error("resident configuration changed within a store");
      return state;
    }
    state.configuration = configuration;
    state.policy = requireCompiled(
      compileLoadout(configuration.graph, configuration.environment),
    ).presence!.find((p) => p.policyId === configuration.policyId)!;
    const machine = new PresenceMachine(state.policy);
    if (!state.present) machine.absence(state.at);
    state.machine = machine.snapshot();
    return state;
  }
  if (event.type === "ClockSampled") {
    const at = payload["at"];
    if (
      typeof at !== "number" ||
      !Number.isFinite(at) ||
      at < 0 ||
      at !== event.occurredAt
    )
      throw new Error("invalid recorded clock sample");
    state.at = Math.max(state.at, at); // A backwards wall clock cannot replenish a phase.
    expireActorHeartbeats(state);
  }
  let humanChanged = false;
  if (event.type === "OperatorPresenceObserved") {
    const observation = decodePresenceObservation(payload);
    if (observation.at !== event.occurredAt)
      throw new Error("presence time differs from event");
    state.at = Math.max(state.at, observation.at);
    // A late heartbeat cannot hide a deadline crossed before its arrival.
    expireActorHeartbeats(state);
    const { signal, origin, stamp } = observation;
    if (
      origin === "human" &&
      observation.at >= state.at &&
      observation.at >= (state.lastHumanAt ?? 0)
    ) {
      state.lastHumanAt = observation.at;
      state.present = signal.kind !== "away";
      humanChanged = true;
    }
    if (origin === "actor" && signal.kind === "heartbeat") {
      const key = presenceActorKey(signal, stamp);
      const old = state.actors[key];
      // A late heartbeat cannot resurrect a completed/lost resident episode.
      if (
        observation.at >= state.at &&
        (!stamp ||
          !["observed", "lost"].includes(
            state.episodes[stamp.episodeId] ?? "",
          )) &&
        (!old || observation.at >= old.lastHeartbeatAt)
      ) {
        state.actors[key] = {
          lastHeartbeatAt: observation.at,
          status: "live",
          ...(stamp ? { episodeId: stamp.episodeId } : {}),
          ...(old?.failureAt === undefined ? {} : { failureAt: old.failureAt }),
        };
      }
    }
    if (origin === "task" && signal.kind === "progress")
      state.progress = {
        ...state.progress,
        [signal.taskId]: Math.max(
          Object.hasOwn(state.progress, signal.taskId)
            ? state.progress[signal.taskId]!
            : 0,
          observation.at,
        ),
      };
  }
  if (event.type === "OperatorPresenceChanged") {
    if (
      typeof payload["presence"] !== "string" ||
      !["away", "returned"].includes(payload["presence"])
    )
      throw new Error("invalid resident presence");
    state.present = payload["presence"] === "returned";
    state.lastHumanAt = state.at;
    humanChanged = true;
  }
  if (
    event.type === "ClockSampled" &&
    state.present &&
    state.lastHumanAt !== null &&
    state.policy?.humanIdleMs !== undefined &&
    state.at - state.lastHumanAt >= state.policy.humanIdleMs
  ) {
    state.present = false;
    humanChanged = true;
  }
  if (!state.machine) {
    if (
      ![
        "ClockSampled",
        "OperatorPresenceChanged",
        "OperatorPresenceObserved",
      ].includes(event.type)
    )
      throw new Error("resident event precedes configuration");
    return state;
  }
  const machine = residentMachine(state, predicates);
  machine.now = state.at;
  if (humanChanged) {
    if (state.present) machine.returned();
    else machine.absence();
  }
  if (event.type === "ClockSampled") machine.transition("idle-expired");
  if (
    state.policy!.phases.some(
      (phase) =>
        phase.effectiveEnvelope.revocationEventTypes.includes(event.type) ||
        phase.effectiveEnvelope.revocationConditions?.length,
    )
  )
    state.revokedBy.push(event);
  if (event.type === "ScriptEpisodeDispatched") {
    const dueAt = machine.due(state.at);
    const id = payload["episodeId"];
    const phase = machine.phase();
    const spec = phase ? state.configuration!.actors[phase.phaseId]! : null;
    if (
      typeof id !== "string" ||
      dueAt === null ||
      id !== residentEpisodeId(machine, dueAt) ||
      Object.hasOwn(state.episodes, id) ||
      payload["dueAt"] !== dueAt ||
      payload["phaseId"] !== phase!.phaseId ||
      payload["kind"] !== spec!.kind ||
      payload["effect"] !== spec!.effect ||
      payload["authorityEnvelopeId"] !==
        phase!.effectiveEnvelope.authorityEnvelopeId ||
      residentRefusal(state, machine)
    )
      throw new Error("invalid or repeated resident dispatch");
    state.episodes[id] = "dispatched";
    state.episodePhases[id] = phase!.phaseId;
    state.episodeGenerations[id] = machine.generation;
    state.actors[`episode:${id}`] = {
      lastHeartbeatAt: state.at,
      status: "live",
      episodeId: id,
    };
    machine.dispatch(id);
    state.lastNoOp = null;
  }
  if (event.type === "HandoffRequested") {
    const packet = payload["packet"];
    assertHandoffPacket(packet);
    const id = packet.episodeId;
    const phaseId = state.episodePhases[id];
    const spec = phaseId ? state.configuration!.actors[phaseId] : undefined;
    if (
      state.episodes[id] !== "dispatched" ||
      !spec?.handoff ||
      canonicalStringify(packet) !==
        canonicalStringify({ ...spec.handoff, episodeId: id }) ||
      Object.values(state.handoffs).some(
        (h) =>
          h.packet.workOrderId === packet.workOrderId && h.answer === undefined,
      )
    )
      throw new Error("invalid or repeated handoff request");
    state.handoffs[id] = {
      packet,
      phaseId: phaseId!,
      generation: state.episodeGenerations[id]!,
    };
    state.episodes[id] = "observed";
    state.actors[`episode:${id}`]!.status = "stopped";
    // Waiting is durable state, not a live actor or an occupied process slot.
    machine.waitForInput(id);
  }
  if (event.type === "HandoffAnswered") {
    const id = payload["episodeId"];
    const handoff = typeof id === "string" ? state.handoffs[id] : undefined;
    const option = payload["optionId"];
    if (
      event.actorId !== "operator" ||
      payload["origin"] !== "human" ||
      !handoff ||
      handoff.answer !== undefined ||
      payload["workOrderId"] !== handoff.packet.workOrderId ||
      typeof option !== "string" ||
      !handoff.packet.options.some((o) => o.id === option)
    )
      throw new Error("invalid, stale or repeated human handoff answer");
    handoff.answer = option;
    state.at = Math.max(state.at, event.occurredAt);
    machine.now = state.at;
    machine.transition("idle-expired");
    if (
      !machine.present &&
      !machine.current &&
      machine.state === handoff.phaseId &&
      machine.generation === handoff.generation
    ) {
      machine.dispatch(handoff.packet.episodeId);
      machine.outcome("verified-success", handoff.packet.episodeId);
    }
    state.lastNoOp = null;
  }
  if (
    [
      "ScriptEpisodeObserved",
      "CliWorkerObserved",
      "ScriptEpisodeLost",
    ].includes(event.type)
  ) {
    const id = payload["episodeId"];
    if (typeof id !== "string" || state.episodes[id] !== "dispatched")
      throw new Error("resident outcome has no pending dispatch");
    const lost = event.type === "ScriptEpisodeLost";
    if (lost && (typeof payload["reason"] !== "string" || !payload["reason"]))
      throw new Error("lost episode needs a reason");
    if (!lost) {
      assertActorResult(payload);
      const spec = state.configuration!.actors[state.episodePhases[id]!]!;
      if ((event.type === "CliWorkerObserved") !== (spec.kind === "cli-worker"))
        throw new Error("actor observation kind differs from dispatch");
      const verified = scriptResultVerified(spec, payload, id);
      if (payload.verified !== verified)
        throw new Error("script verification contradicts recorded output");
    }
    state.episodes[id] = lost ? "lost" : "observed";
    const actor = state.actors[`episode:${id}`];
    if (actor) actor.status = "stopped";
    machine.outcome(
      !lost && payload["verified"] === true ? "verified-success" : "failure",
      id,
    );
  }
  if (["ActorUnavailable", "ScriptEpisodeRefused"].includes(event.type)) {
    if (
      typeof payload["reason"] !== "string" ||
      !payload["reason"] ||
      !state.policy!.phases.some((p) => p.phaseId === payload["phaseId"])
    )
      throw new Error("resident NoOp needs a reason and phase");
    state.lastNoOp = payload["reason"];
  }
  state.machine = machine.snapshot();
  return state;
}

/** Replayable observations. No process, launch-path or ambient-clock input. */
export const PRESENCE_HOOK_EVENTS = [
  "UserPromptSubmit",
  "PreToolUse",
  "PostToolUse",
  "Stop",
] as const;
export type PresenceHookEvent = (typeof PRESENCE_HOOK_EVENTS)[number];
export type PresenceSignal =
  | { kind: "away" }
  | { kind: "back" }
  | {
      kind: "heartbeat";
      event: PresenceHookEvent;
      sessionId: string;
      interaction?: "human" | "scripted" | "unknown";
    }
  | { kind: "progress"; taskId: string };
export interface ResidentStamp {
  episodeId: string;
}
export interface OperatorPresenceObserved {
  signal: PresenceSignal;
  origin: "human" | "actor" | "task";
  at: number;
  stamp?: ResidentStamp;
}

export function classifyPresenceSignal(
  signal: PresenceSignal,
  stamp?: ResidentStamp,
): OperatorPresenceObserved["origin"] {
  if (signal.kind === "progress") return "task";
  if (signal.kind === "away" || signal.kind === "back") return "human";
  return !stamp &&
    signal.event === "UserPromptSubmit" &&
    signal.interaction === "human"
    ? "human"
    : "actor";
}
const identity = (value: unknown): value is string =>
  typeof value === "string" &&
  value.length > 0 &&
  value.length <= 256 &&
  !/[\u0000-\u0020\u007f]/u.test(value);
export function decodePresenceObservation(
  value: unknown,
): OperatorPresenceObserved {
  const fail = (): never => {
    throw new Error("invalid presence observation");
  };
  if (!value || typeof value !== "object" || Array.isArray(value))
    return fail();
  const v = value as OperatorPresenceObserved;
  if (
    Object.keys(v).some(
      (k) => !["signal", "origin", "at", "stamp"].includes(k),
    ) ||
    !Number.isFinite(v.at) ||
    v.at < 0 ||
    !v.signal ||
    typeof v.signal !== "object" ||
    Array.isArray(v.signal)
  )
    return fail();
  if (
    v.stamp !== undefined &&
    (!v.stamp ||
      typeof v.stamp !== "object" ||
      Array.isArray(v.stamp) ||
      Object.keys(v.stamp).some((k) => k !== "episodeId") ||
      !identity(v.stamp.episodeId))
  )
    return fail();
  const s = v.signal;
  let keys: string[];
  switch (s.kind) {
    case "away":
    case "back":
      keys = ["kind"];
      if (v.stamp) return fail();
      break;
    case "heartbeat":
      keys = ["kind", "event", "sessionId", "interaction"];
      if (
        !PRESENCE_HOOK_EVENTS.includes(s.event) ||
        !identity(s.sessionId) ||
        (s.interaction !== undefined &&
          !["human", "scripted", "unknown"].includes(s.interaction))
      )
        return fail();
      break;
    case "progress":
      keys = ["kind", "taskId"];
      if (!identity(s.taskId) || v.stamp) return fail();
      break;
    default:
      return fail();
  }
  if (
    Object.keys(s).some((k) => !keys.includes(k)) ||
    v.origin !== classifyPresenceSignal(s, v.stamp)
  )
    return fail();
  return structuredClone(v);
}
export const presenceActorKey = (
  signal: Extract<PresenceSignal, { kind: "heartbeat" }>,
  stamp?: ResidentStamp,
) => (stamp ? `episode:${stamp.episodeId}` : `session:${signal.sessionId}`);

import type {
  CompiledPresencePolicy,
  PresenceTransition,
} from "@dotln/compiler";
import {
  evaluateCadence,
  type JsonValue,
  type PredicateRegistry,
} from "@dotln/kernel";

const field = (state: JsonValue, key: string) =>
  (state as Record<string, JsonValue>)[key];
export const presencePredicates: PredicateRegistry = {
  "dotln.presence.phase-ready": {
    1: ({ state }, params) =>
      field(state, "present") === false &&
      field(state, "phase") === params["phaseId"] &&
      field(state, "policyId") === params["policyId"] &&
      field(state, "inFlight") === false,
  },
  "dotln.presence.returned": {
    1: ({ state }) => field(state, "present") === true,
  },
  "dotln.presence.interrupt-phase": {
    1: ({ state }, params) =>
      field(state, "present") === true &&
      params["discretionary"] === true &&
      params["inFlightOnReturn"] === "kill",
  },
};
export interface PresenceSnapshot {
  state: string;
  present: boolean;
  now: number;
  armedAt: number;
  lastActivity: number;
  generation: number;
  current: {
    id: string;
    generation: number;
    discretionary: boolean;
    status: string;
  } | null;
}

/** The WO-067 table interpreter. All time and outcomes are explicit inputs. */
export class PresenceMachine {
  state: string;
  present = true;
  now = 0;
  armedAt = 0;
  lastActivity = 0;
  generation = 0;
  current: PresenceSnapshot["current"] = null;
  readonly transcript: string[] = [];
  constructor(
    readonly compiled: CompiledPresencePolicy,
    readonly predicates: PredicateRegistry = presencePredicates,
    snapshot?: PresenceSnapshot,
  ) {
    this.state = compiled.statechart.initial;
    if (snapshot) Object.assign(this, structuredClone(snapshot));
  }
  snapshot(): PresenceSnapshot {
    const { state, present, now, armedAt, lastActivity, generation, current } =
      this;
    return { state, present, now, armedAt, lastActivity, generation, current };
  }
  phase() {
    return this.compiled.phases.find((phase) => phase.phaseId === this.state);
  }
  projected() {
    return {
      present: this.present,
      phase: this.state,
      policyId: this.compiled.policyId,
      inFlight: this.current !== null,
    };
  }
  transition(on: PresenceTransition["on"], episode?: string) {
    const transition = this.compiled.statechart.transitions.find(
      (t) => t.from === this.state && t.on === on,
    );
    if (!transition) return;
    if (
      transition.guard === "current-policy-episode-while-absent" &&
      (this.present ||
        !this.current ||
        episode !== this.current.id ||
        this.current.generation !== this.generation)
    )
      return;
    if (transition.guard === "idle-deadline-while-absent") {
      const deadline = evaluateCadence(
        this.compiled.idleCadence,
        this.projected(),
        { now: this.lastActivity, rngState: 0, predicates: this.predicates },
      );
      if (
        this.present ||
        this.current ||
        deadline.dueAt === null ||
        this.now < deadline.dueAt
      )
        return;
    }
    this.state = transition.to;
    for (const action of transition.actions) {
      switch (action) {
        case "arm-phase":
          this.armedAt = this.now;
          this.lastActivity = this.now;
          break;
        case "cancel-pending":
        case "reset-progress":
          this.generation += 1;
          break;
        case "expire-phase":
          this.transcript.push("expired:attention,work-scope,effect-authority");
          break;
        case "finish-discretionary":
          if (this.current?.discretionary) {
            this.current.status = "finishing";
            this.transcript.push("in-flight:finish");
          }
          break;
        case "kill-discretionary":
          if (this.current?.discretionary) {
            this.current = null;
            this.transcript.push("in-flight:kill");
          }
          break;
        case "preserve-foreground":
          break; // Foreground state is owned by its own slice.
      }
    }
    this.transcript.push(`${on}:${this.state}`);
  }
  absence(at = this.now) {
    this.now = at;
    if (!this.present) return;
    this.present = false;
    this.transition("absence");
  }
  returned(at = this.now) {
    this.now = at;
    this.present = true;
    this.transition("return");
  }
  outcome(
    kind: "verified-success" | "failure" | "unverified",
    episode: string,
    at = this.now,
  ) {
    this.now = at;
    if (kind !== "unverified") this.transition(kind, episode);
    if (kind !== "unverified" && this.current?.id === episode) {
      this.current = null;
      this.lastActivity = at;
    }
  }
  /** A durable human question frees the process slot without failing/resetting
   * the policy. Its recorded generation binds the later answer continuation. */
  waitForInput(episode: string) {
    if (this.current?.id === episode) this.current = null;
  }
  due(at: number): number | null {
    this.now = at;
    this.transition("idle-expired");
    const phase = this.phase();
    if (!phase) {
      this.transcript.push(`NoOp:${this.state}`);
      return null;
    }
    const evaluation = evaluateCadence(phase.cadence, this.projected(), {
      now: this.armedAt,
      rngState: 0,
      predicates: this.predicates,
    });
    if (evaluation.dueAt === null || at < evaluation.dueAt) {
      this.transcript.push("NoOp:gate-or-cadence");
      return null;
    }
    if (phase.availability.kind === "NoOp") {
      this.transcript.push(`NoOp:${phase.availability.reason}`);
      return null;
    }
    return evaluation.dueAt;
  }
  dispatch(id: string) {
    const phase = this.phase();
    if (!phase || this.present || this.current)
      throw new Error("presence dispatch is not ready");
    this.current = {
      id,
      generation: this.generation,
      discretionary: phase.discretionary,
      status: "running",
    };
    this.lastActivity = this.now;
    this.transcript.push(`dispatch:${phase.phaseId}`);
  }
}

